modules=[]
lesson_index=[]
def task(title,prompt,sql,difficulty='Beginner',kind='query',starter=None,validation=None,ordered=True,names=True,hints=None,explanation=None):
    return dict(title=title,prompt=prompt,difficulty=difficulty,kind=kind,starterSQL=starter if starter is not None else '-- Write your PostgreSQL query here\n',solutionSQL=sql,fixtureIDs=['retail','retail-edge'],ordered=ordered,columnNames=names,hints=hints or ['Identify the rows and columns requested before writing SQL.','Build the query in small parts and run it after each change.'],explanation=explanation or 'The reference solution expresses the requested rule over the fixture data. Equivalent solutions are accepted when their columns, values, duplicates, and required order agree.',**({'validationSQL':validation} if validation else {}))
def module(title):
    m=dict(id=f'm{len(modules)+1:02}',title=title,topics=[]); modules.append(m); return m

def lesson(m,title,meaning,why,how,mistake,tasks,prereq=None):
    n=len(lesson_index)+1; lid=f'l{n:03}'
    for i,t in enumerate(tasks): t['id']=f'{lid}-e{i+1}'
    sections=[
        dict(title='The idea',body=meaning),
        dict(title='Why it exists',body=why),
        dict(title='How it works',body=how),
        dict(title='Read the syntax',body='Read the example from its data source through its filtering and output expressions. SQL keywords describe operations; identifiers name objects; single quotes contain text. Run this complete example on the Retail dataset.',code=tasks[0]['solutionSQL']),
        dict(title='A small example',body=tasks[0]['prompt'],code=tasks[0]['solutionSQL']),
        dict(title='A realistic use',body=tasks[-1]['prompt'],code=tasks[-1]['solutionSQL']),
        dict(title='Expected results',body='Expected results are verified against PostgreSQL 18 during course validation. Use the exercise result table to inspect each column and NULL. The same rule must work on the additional dataset too.'),
        dict(title='Common mistakes',body=mistake),
        dict(title='Connections',body='Prerequisites: '+(', '.join(prereq) if prereq else ('Tables, rows, and basic expressions' if n>2 else 'No previous SQL knowledge'))+'. Compare the small example with the realistic task: the concept stays the same when more rows are added.'),
        dict(title='Practice deliberately',body='Complete the three exercises in order. Run a draft, inspect its rows, then submit. A wrong result does not erase your progress. Use one hint at a time and mark this lesson for review if you needed the worked solution.'),
        dict(title='Recap',body=meaning+' '+how.split('. ')[0]+'.')]
    l=dict(id=lid,title=title,prerequisites=prereq or ([lesson_index[-1]['id']] if lesson_index else []),sections=sections,exercises=tasks)
    topic=dict(id=f'{lid}-topic',title=title,lessons=[l]);m['topics'].append(topic);lesson_index.append(l)
    return l

m=module('Database Fundamentals')
lesson(m,'Tables, rows, and columns','A relational database stores facts in tables. A row describes one thing; a column describes one property. A DBMS is the software that stores, protects, and queries those facts.','A shared structure lets many applications agree on names and data types without duplicating the facts.','SELECT chooses columns. FROM names a table. A semicolon ends the statement. PostgreSQL is the DBMS used throughout this course.','A table is not a spreadsheet with guaranteed row positions. Use ORDER BY whenever row order matters.',[
 task('Meet the customers','Return every column of customers, ordered by id.','SELECT * FROM customers ORDER BY id;'),
 task('Inspect the catalog','Return id, name, and price from products, ordered by id.','SELECT id, name, price FROM products ORDER BY id;'),
 task('Read a business record','Return id, customer_id, ordered_on, status, and total from orders, ordered by id.','SELECT id, customer_id, ordered_on, status, total FROM orders ORDER BY id;')])
lesson(m,'Keys and relationships','A primary key identifies one row. A foreign key points to a row in another table. A schema is a namespace containing tables and other objects.','Keys connect facts without copying a customer name into every order. Constraints reject relationships that cannot be valid. Relationship map: customers.id (one) → orders.customer_id (many); orders.id (one) → order_items.order_id (many); products.id (one) → order_items.product_id (many).','customers.id is unique. orders.customer_id refers to customers.id and may be NULL for a guest order. order_items has a two-column primary key.','An identifier and a display name have different jobs. Different people can share a name, and a NULL foreign key means no known related row.',[
 task('Read customer identities','Return id and name from customers, ordered by id.','SELECT id, name FROM customers ORDER BY id;'),
 task('Read order relationships','Return id and customer_id from orders, ordered by id.','SELECT id, customer_id FROM orders ORDER BY id;'),
 task('Read a composite key','Return order_id, product_id, and quantity from order_items, ordered by order_id then product_id.','SELECT order_id, product_id, quantity FROM order_items ORDER BY order_id, product_id;')])
lesson(m,'Expressions and query order','An expression computes a value. SQL is declarative: you describe the answer rather than a loop through the data.','The database can choose an efficient plan while preserving the meaning of your query.','The logical pipeline starts with FROM and WHERE, then grouping and HAVING, then SELECT, DISTINCT, ordering, and limiting. The physical plan may differ.','SELECT aliases usually are not available in WHERE. Integer division truncates; use a numeric operand when fractions matter.',[
 task('Compute a constant','Return one column named answer containing 2 + 3 * 4.','SELECT 2 + 3 * 4 AS answer;'),
 task('Value the inventory','Return id and stock_value (price multiplied by stock) from products, ordered by id.','SELECT id, price * stock AS stock_value FROM products ORDER BY id;'),
 task('Compute line revenue','Return order_id, product_id, and revenue (quantity times unit_price) from order_items in key order.','SELECT order_id, product_id, quantity * unit_price AS revenue FROM order_items ORDER BY order_id, product_id;')])

m=module('SELECT and Result Shape')
lesson(m,'Projection and aliases','Projection means choosing the columns of the result. An alias gives a result column a clear name.','A focused result is easier to read, uses less transfer, and makes an application contract explicit.','Write a comma-separated output list after SELECT. AS introduces an alias. Unquoted names become lowercase.','SELECT * changes when the table changes. Double quotes identify names; single quotes create text values.',[
 task('Clear product headings','Return name as product and price as unit_price, ordered by product id.','SELECT name AS product, price AS unit_price FROM products ORDER BY id;'),
 task('Customer labels','Return id and name as customer_name from customers, ordered by id.','SELECT id, name AS customer_name FROM customers ORDER BY id;'),
 task('Shipment report','Return order id as order_number and shipped_on as dispatch_date, ordered by id.','SELECT id AS order_number, shipped_on AS dispatch_date FROM orders ORDER BY id;')])
lesson(m,'DISTINCT and duplicate values','DISTINCT removes duplicate result rows after the output expressions have been evaluated.','Reports often need unique categories rather than one row for every product.','DISTINCT applies to the entire selected row, not just the first selected column. NULLs are treated as equal for duplicate elimination.','Adding id to a DISTINCT category query makes every row unique again.',[
 task('Unique categories','Return distinct product category values, ordered alphabetically.','SELECT DISTINCT category FROM products ORDER BY category;'),
 task('Cities including unknown','Return distinct customer city values, ordered alphabetically with NULL last.','SELECT DISTINCT city FROM customers ORDER BY city NULLS LAST;'),
 task('Status by month','Return distinct month numbers as month and status from orders, ordered by month and status.','SELECT DISTINCT EXTRACT(MONTH FROM ordered_on)::integer AS month, status FROM orders ORDER BY month, status;','Intermediate')])
lesson(m,'ORDER BY, LIMIT, and OFFSET','ORDER BY establishes a result order. LIMIT chooses a maximum number of rows; OFFSET skips rows.','Pagination and top-N reports need a predictable ordering contract.','Sort keys are evaluated left to right. DESC reverses one key. Add a unique tie-breaker to make limited results deterministic.','LIMIT without ORDER BY does not mean the first inserted rows. Large OFFSET values still require work to skip rows.',[
 task('Most expensive products','Return id, name, and price for the three most expensive products; break price ties by id ascending.','SELECT id, name, price FROM products ORDER BY price DESC, id LIMIT 3;'),
 task('Second page','Return id and name of products ordered by id, skipping two rows and taking three.','SELECT id, name FROM products ORDER BY id LIMIT 3 OFFSET 2;'),
 task('Unshipped first','Return id and shipped_on from orders, NULL shipment dates first, then shipped_on ascending and id ascending.','SELECT id, shipped_on FROM orders ORDER BY shipped_on NULLS FIRST, id;','Intermediate')])

m=module('Filtering and Boolean Logic')
lesson(m,'WHERE and comparisons','WHERE keeps rows for which its condition is true. Comparisons produce Boolean values: true, false, or unknown.','Filtering lets a report focus on a business condition at the database.','Use =, <>, <, <=, >, and >= to compare compatible values. WHERE runs before grouping.','Use = for equality, not ==. Comparing a value to NULL with = does not produce true.',[
 task('Affordable products','Return id, name, and price for products costing less than 20, ordered by id.','SELECT id, name, price FROM products WHERE price < 20 ORDER BY id;'),
 task('Paid orders','Return id and total for paid orders, ordered by id.','SELECT id, total FROM orders WHERE status = \'paid\' ORDER BY id;'),
 task('Stock warning','Return id, name, and stock for products with at most 8 in stock, ordered by stock then id.','SELECT id, name, stock FROM products WHERE stock <= 8 ORDER BY stock, id;')])
lesson(m,'AND, OR, NOT, and precedence','AND requires both conditions. OR accepts either condition. NOT reverses a Boolean condition.','Business rules often combine category, value, and status conditions.','NOT binds before AND, and AND binds before OR. Parentheses make the intended grouping explicit.','A missing pair of parentheses can include rows that bypass part of a filter.',[
 task('In-stock office goods','Return id and name for Office products with stock above zero, ordered by id.','SELECT id, name FROM products WHERE category = \'Office\' AND stock > 0 ORDER BY id;'),
 task('Two departments','Return id and name for employees in Sales or Engineering with salary at least 80000, ordered by id.','SELECT id, name FROM employees WHERE (department = \'Sales\' OR department = \'Engineering\') AND salary >= 80000 ORDER BY id;','Intermediate'),
 task('Exclude pending and cancelled','Return id and total from orders whose status is neither pending nor cancelled, ordered by id.','SELECT id, total FROM orders WHERE NOT (status = \'pending\' OR status = \'cancelled\') ORDER BY id;')])
lesson(m,'IN, BETWEEN, and ranges','IN tests membership in a list. BETWEEN includes both endpoints. A half-open range includes its start and excludes its end.','Short, explicit range predicates reduce repeated logic and handle time boundaries cleanly.','Use IN for discrete alternatives. Use >= start AND < end for a date or timestamp period when adjacent periods must not overlap.','BETWEEN on timestamps through a final date includes only midnight of that date unless the endpoint says otherwise.',[
 task('Selected categories','Return id and name of Home or Office products, ordered by id.','SELECT id, name FROM products WHERE category IN (\'Home\',\'Office\') ORDER BY id;'),
 task('Mid-price range','Return id and price for products with price between 10 and 75 inclusive, ordered by id.','SELECT id, price FROM products WHERE price BETWEEN 10 AND 75 ORDER BY id;'),
 task('June orders','Return id and ordered_on from orders placed in June 2024, ordered by id.','SELECT id, ordered_on FROM orders WHERE ordered_on >= DATE \'2024-06-01\' AND ordered_on < DATE \'2024-07-01\' ORDER BY id;','Intermediate')])

m=module('NULL and Text Matching')
lesson(m,'NULL and three-valued logic','NULL represents a missing or unknown value. It is not zero, an empty string, or a special ordinary value.','Real data often has unknown shipment dates or optional contact details. SQL keeps that uncertainty visible.','Use IS NULL and IS NOT NULL. WHERE keeps true only; false and unknown are discarded. IS DISTINCT FROM compares NULLs as values.','NOT IN can become unknown when its list or subquery contains NULL. Use NOT EXISTS for nullable anti-joins.',[
 task('Missing email','Return id and name for customers whose email is NULL, ordered by id.','SELECT id, name FROM customers WHERE email IS NULL ORDER BY id;'),
 task('Known shipment dates','Return id and shipped_on for shipped orders, ordered by id.','SELECT id, shipped_on FROM orders WHERE shipped_on IS NOT NULL ORDER BY id;'),
 task('Not London, including unknown','Return id and city for customers whose city is distinct from London, including NULL cities, ordered by id.','SELECT id, city FROM customers WHERE city IS DISTINCT FROM \'London\' ORDER BY id;','Intermediate')])
lesson(m,'LIKE, ILIKE, and escaping','LIKE matches a pattern. Percent matches any string; underscore matches one character. PostgreSQL ILIKE ignores case according to locale.','Text searches often need prefixes, suffixes, and case-insensitive matching.','Surround a fragment with percent signs for contains. Escape wildcard characters when they must match literally.','LIKE is not a regular expression. A leading wildcard often prevents a plain B-tree prefix search.',[
 task('Notebook family','Return id and name of products whose name starts with Notebook, ordered by id.','SELECT id, name FROM products WHERE name LIKE \'Notebook%\' ORDER BY id;'),
 task('Case-insensitive match','Return id and name of customers whose name contains the letter a, ignoring case, ordered by id.','SELECT id, name FROM customers WHERE name ILIKE \'%a%\' ORDER BY id;'),
 task('Literal underscore','Return id and name of customers whose name contains a literal underscore, ordered by id.','SELECT id, name FROM customers WHERE name LIKE \'%!_%\' ESCAPE \'!\' ORDER BY id;','Intermediate')])
lesson(m,'Regular expressions','A regular expression describes a richer text pattern than LIKE. PostgreSQL uses POSIX-style regular expressions.','Validation and extraction sometimes need character classes, repetition, and boundaries.','The ~ operator matches case-sensitively; ~* ignores case. Anchors ^ and $ mark the beginning and end.','Do not assume an unanchored pattern matches the entire value. Complex patterns can be expensive on long text.',[
 task('Names beginning A through D','Return id and name of customers whose name begins with A, B, C, or D, ordered by id.','SELECT id, name FROM customers WHERE name ~ \'^[A-D]\' ORDER BY id;'),
 task('Email shape','Return id and email for customers whose email ends with @example.test, ordered by id.','SELECT id, email FROM customers WHERE email ~ \'@example[.]test$\' ORDER BY id;'),
 task('Extract an email user','Return id and the email text before @ as username for customers with known emails, ordered by id.','SELECT id, substring(email FROM \'^[^@]+\') AS username FROM customers WHERE email IS NOT NULL ORDER BY id;','Intermediate')])

m=module('Expressions, CASE, and Casts')
lesson(m,'CASE and conditional values','CASE returns a value chosen by conditions. It is an expression and can appear wherever a value is needed.','Reports translate raw values into useful business labels without changing the source rows.','Searched CASE tests WHEN conditions in order and returns the first matching THEN value. ELSE handles the remaining cases.','If ELSE is omitted, unmatched rows produce NULL. Put more specific conditions before broader ones.',[
 task('Stock labels','Return id and a stock_status of empty when stock is 0, low when stock is below 10, otherwise ready; order by id.','SELECT id, CASE WHEN stock = 0 THEN \'empty\' WHEN stock < 10 THEN \'low\' ELSE \'ready\' END AS stock_status FROM products ORDER BY id;'),
 task('Order bands','Return id and a size_band of large for totals at least 100, medium for totals at least 25, otherwise small, ordered by id.','SELECT id, CASE WHEN total >= 100 THEN \'large\' WHEN total >= 25 THEN \'medium\' ELSE \'small\' END AS size_band FROM orders ORDER BY id;'),
 task('VIP priority','Return id and priority: 1 for VIP customers, 2 for other customers in London, 3 otherwise. Order by priority then id.','SELECT id, CASE WHEN vip THEN 1 WHEN city = \'London\' THEN 2 ELSE 3 END AS priority FROM customers ORDER BY priority, id;','Intermediate')])
lesson(m,'COALESCE, NULLIF, and safe arithmetic','COALESCE chooses the first non-NULL value. NULLIF returns NULL when two values are equal.','These expressions make fallback labels and safe ratios concise.','Wrap a potentially zero denominator in NULLIF(value,0). COALESCE can then choose a display value if a fallback is truly appropriate.','Replacing missing numeric facts with zero changes their meaning and can change an average.',[
 task('Unknown city label','Return id and city_label using Unknown for a NULL city, ordered by id.','SELECT id, COALESCE(city, \'Unknown\') AS city_label FROM customers ORDER BY id;'),
 task('Safe price per stock unit','Return id and ratio equal to price divided by stock, rounded to two decimals; return NULL when stock is zero. Order by id.','SELECT id, round(price / NULLIF(stock,0),2) AS ratio FROM products ORDER BY id;','Intermediate'),
 task('Email fallback','Return id and contact, taking email when known and otherwise name, ordered by id.','SELECT id, COALESCE(email,name) AS contact FROM customers ORDER BY id;')])
lesson(m,'Casts and numeric precision','A cast converts a value to another data type when PostgreSQL has an appropriate conversion. NUMERIC represents exact decimal quantities.','Money and ratios require deliberate precision; implicit conversions can hide errors.','CAST(value AS type) and value::type are equivalent forms. Integer division discards the fraction; casting an operand to numeric preserves it.','A cast can fail on invalid text. Floating-point values are approximate and should not be compared as exact money.',[
 task('Preserve a fraction','Return one column ratio equal to 5 divided by 2 as a numeric fraction.','SELECT 5::numeric / 2 AS ratio;'),
 task('Round a tax amount','Return id and tax equal to price multiplied by 0.075, rounded to two decimals, ordered by id.','SELECT id, round(price * 0.075,2) AS tax FROM products ORDER BY id;'),
 task('Dates from timestamps','Return event id and event_date by casting occurred_at to date, ordered by id.','SELECT id, occurred_at::date AS event_date FROM events ORDER BY id;','Intermediate')])

m=module('Aggregate Functions')
lesson(m,'COUNT and missing values','An aggregate combines many input rows into one value. COUNT(*) counts rows, while COUNT(expression) counts non-NULL values.','Summary metrics compress a dataset without requiring application loops.','COUNT returns zero for no input rows. Other common aggregates usually return NULL on an empty input.','COUNT(city) does not count customers with unknown cities. COUNT(DISTINCT city) also removes duplicate known cities.',[
 task('Count customers','Return customer_count containing the number of customer rows.','SELECT count(*) AS customer_count FROM customers;'),
 task('Count known emails','Return total_customers and known_emails using COUNT(*) and COUNT(email).','SELECT count(*) AS total_customers, count(email) AS known_emails FROM customers;'),
 task('Count unique cities','Return city_count containing the number of distinct non-NULL customer cities.','SELECT count(DISTINCT city) AS city_count FROM customers;','Intermediate')])
lesson(m,'SUM, AVG, MIN, and MAX','SUM adds values; AVG computes their mean; MIN and MAX find the smallest and largest non-NULL values.','Sales, stock, and salary reports need compact measures with clear units.','The aggregate sees rows left after WHERE. Multiple aggregates can share one scan and produce one result row.','AVG ignores NULLs and is not the same as SUM divided by COUNT(*). AVG of group averages is often wrong.',[
 task('Catalog statistics','Return minimum_price, maximum_price, and average_price rounded to two decimals from products.','SELECT min(price) AS minimum_price, max(price) AS maximum_price, round(avg(price),2) AS average_price FROM products;'),
 task('Paid revenue','Return revenue equal to the sum of total on paid orders.','SELECT sum(total) AS revenue FROM orders WHERE status = \'paid\';'),
 task('Stock valuation','Return inventory_value equal to sum of price times stock, and unit_count equal to sum of stock, from products.','SELECT sum(price * stock) AS inventory_value, sum(stock) AS unit_count FROM products;','Intermediate')])
lesson(m,'FILTER and conditional aggregation','FILTER applies a condition to one aggregate. CASE inside an aggregate is another way to express conditional summaries.','A dashboard can compare several segments in one result without running separate queries.','Write aggregate(...) FILTER (WHERE condition). The outer WHERE still filters the input for every aggregate.','SUM(CASE WHEN condition THEN 1 END) yields NULL when nothing matches. COUNT with FILTER returns zero.',[
 task('Order status counts','Return paid_count and pending_count as counts of paid and pending orders.','SELECT count(*) FILTER (WHERE status = \'paid\') AS paid_count, count(*) FILTER (WHERE status = \'pending\') AS pending_count FROM orders;','Intermediate'),
 task('Conditional revenue','Return paid_revenue and cancelled_revenue as sums of total for each named status.','SELECT sum(total) FILTER (WHERE status = \'paid\') AS paid_revenue, sum(total) FILTER (WHERE status = \'cancelled\') AS cancelled_revenue FROM orders;','Intermediate'),
 task('VIP share','Return vip_count and other_count as counts of VIP and non-VIP customers.','SELECT sum(CASE WHEN vip THEN 1 ELSE 0 END) AS vip_count, sum(CASE WHEN NOT vip THEN 1 ELSE 0 END) AS other_count FROM customers;','Intermediate')])

m=module('GROUP BY and HAVING')
lesson(m,'Group rows into summaries','GROUP BY forms groups of rows that share grouping values, then calculates aggregates for each group.','Category and department summaries answer business questions at a different level of detail.','Every output expression must be grouped or aggregated, except columns that PostgreSQL can prove functionally dependent on grouped primary keys.','Grouping by too many columns changes the question. A NULL grouping value forms its own group.',[
 task('Products by category','Return category and product_count for each category, ordered by category.','SELECT category, count(*) AS product_count FROM products GROUP BY category ORDER BY category;'),
 task('Revenue by status','Return status and revenue as sum of total, ordered by status.','SELECT status, sum(total) AS revenue FROM orders GROUP BY status ORDER BY status;'),
 task('Salary by department','Return department, employee_count, and average_salary rounded to two decimals, ordered by department.','SELECT department, count(*) AS employee_count, round(avg(salary),2) AS average_salary FROM employees GROUP BY department ORDER BY department;','Intermediate')])
lesson(m,'HAVING filters groups','HAVING filters completed groups using aggregate conditions. WHERE filters individual rows before grouping.','A report can show only categories with enough products or customers with meaningful spending.','Place HAVING after GROUP BY. Aggregate conditions belong here; ordinary row restrictions usually belong in WHERE.','Moving a row filter into HAVING may change the result or do unnecessary work.',[
 task('Large categories','Return category and product_count for categories with at least 3 products, ordered by category.','SELECT category, count(*) AS product_count FROM products GROUP BY category HAVING count(*) >= 3 ORDER BY category;','Intermediate'),
 task('Repeat customers','Return customer_id and order_count for known customers with at least 2 orders, ordered by customer_id.','SELECT customer_id, count(*) AS order_count FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id HAVING count(*) >= 2 ORDER BY customer_id;','Intermediate'),
 task('High paid spend','Return customer_id and spend for known customers with paid order totals above 100, ordered by customer_id.','SELECT customer_id, sum(total) AS spend FROM orders WHERE status = \'paid\' AND customer_id IS NOT NULL GROUP BY customer_id HAVING sum(total) > 100 ORDER BY customer_id;','Advanced')])
lesson(m,'ROLLUP, CUBE, and GROUPING SETS','Grouping sets compute several grouping levels in one query. ROLLUP adds hierarchical subtotals; CUBE adds every combination.','A report can include details and totals while keeping one source definition.','GROUPING(column) returns 1 when that column is absent from a subtotal grouping set. It distinguishes subtotal NULL from a genuine NULL.','Do not label every NULL as a grand total. A source row can have a NULL grouping value.',[
 task('Category totals and grand total','Return category, units (sum stock), and is_total using GROUPING(category), with details first alphabetically and total last.','SELECT category, sum(stock) AS units, grouping(category) AS is_total FROM products GROUP BY ROLLUP(category) ORDER BY is_total, category;','Advanced'),
 task('Explicit grouping sets','Return status, customer_id, revenue, status_group, and customer_group for separate status totals and customer totals. Sort by status_group, status NULLS LAST, customer_id NULLS LAST.','SELECT status, customer_id, sum(total) AS revenue, grouping(status) AS status_group, grouping(customer_id) AS customer_group FROM orders GROUP BY GROUPING SETS ((status),(customer_id)) ORDER BY status_group, status NULLS LAST, customer_id NULLS LAST;','Advanced'),
 task('Two-dimensional cube','Return department, manager_id, headcount, and grouping_mask from a CUBE of department and manager_id. Order by grouping_mask, department NULLS LAST, manager_id NULLS LAST.','SELECT department, manager_id, count(*) AS headcount, grouping(department,manager_id) AS grouping_mask FROM employees GROUP BY CUBE(department,manager_id) ORDER BY grouping_mask, department NULLS LAST, manager_id NULLS LAST;','Advanced')])

m=module('JOIN Fundamentals')
lesson(m,'INNER JOIN and matching keys','A join combines rows from two data sources. INNER JOIN keeps pairs whose ON condition is true.','Related facts can stay in separate normalized tables and still appear together in a report.','Name each source, give it a short alias, and connect its key columns with ON. One input row can match zero, one, or many rows.','Joining by names instead of keys can create accidental matches. A missing join condition can multiply rows.',[
 task('Name each order customer','Return order id as order_id, customer name as customer, and total for orders with a known customer, ordered by order id.','SELECT o.id AS order_id, c.name AS customer, o.total FROM orders o INNER JOIN customers c ON c.id = o.customer_id ORDER BY o.id;'),
 task('Identify line products','Return order_id, product name as product, and quantity from order_items joined to products, ordered by order_id and product_id.','SELECT i.order_id, p.name AS product, i.quantity FROM order_items i JOIN products p ON p.id = i.product_id ORDER BY i.order_id, i.product_id;'),
 task('Warehouse valuation','Return product_id, product name as product, warehouse, and value (inventory quantity times product price), ordered by product_id.','SELECT i.product_id, p.name AS product, i.warehouse, i.quantity * p.price AS value FROM inventory i JOIN products p ON p.id = i.product_id ORDER BY i.product_id;','Intermediate')])
lesson(m,'LEFT JOIN and preserved rows','LEFT JOIN keeps every left row. If no right row matches, its right-side output columns are NULL.','A customer without orders still belongs in an account report.','Use LEFT JOIN ... ON. A right-side condition in ON limits matches; a right-side condition in WHERE can remove unmatched left rows.','COUNT(*) counts the unmatched placeholder row. COUNT(right_table.id) counts only actual matches.',[
 task('All customers and order IDs','Return customer id as customer_id and order id as order_id, preserving customers with no orders; order by customer_id then order_id NULLS LAST.','SELECT c.id AS customer_id, o.id AS order_id FROM customers c LEFT JOIN orders o ON o.customer_id = c.id ORDER BY c.id, o.id NULLS LAST;','Intermediate'),
 task('Order counts including zero','Return customer id as customer_id and order_count, including customers with zero orders, ordered by customer id.','SELECT c.id AS customer_id, count(o.id) AS order_count FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id ORDER BY c.id;','Intermediate'),
 task('Paid counts including zero','Return customer id as customer_id and paid_count, including every customer, ordered by customer id. Restrict paid status in the join condition.','SELECT c.id AS customer_id, count(o.id) AS paid_count FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = \'paid\' GROUP BY c.id ORDER BY c.id;','Advanced')])
lesson(m,'RIGHT, FULL, and CROSS JOIN','RIGHT JOIN preserves the right source. FULL JOIN preserves both sources. CROSS JOIN produces every possible pair.','Reconciliation needs unmatched rows from both lists; planning sometimes needs every combination.','Outer joins add NULL values for the missing side. CROSS JOIN has no ON predicate. RIGHT JOIN can usually be rewritten by swapping a LEFT JOIN.','A cross product with a million rows on each side is enormous. Filter deliberately before expanding combinations.',[
 task('Preserve every customer with RIGHT JOIN','Return customer id as customer_id and order id as order_id from orders RIGHT JOIN customers; order by customer_id then order_id NULLS LAST.','SELECT c.id AS customer_id, o.id AS order_id FROM orders o RIGHT JOIN customers c ON c.id = o.customer_id ORDER BY c.id, o.id NULLS LAST;','Intermediate'),
 task('Reconcile two ID sets','FULL JOIN customer IDs to order customer IDs, returning distinct customer_id and order_customer_id. Include unmatched values and sort both columns NULLS LAST.','SELECT DISTINCT c.id AS customer_id, o.customer_id AS order_customer_id FROM customers c FULL JOIN orders o ON o.customer_id = c.id ORDER BY customer_id NULLS LAST, order_customer_id NULLS LAST;','Advanced'),
 task('Category and warehouse combinations','Return every distinct category and warehouse pair from the product categories and inventory warehouses, ordered by category then warehouse.','SELECT c.category, w.warehouse FROM (SELECT DISTINCT category FROM products) c CROSS JOIN (SELECT DISTINCT warehouse FROM inventory) w ORDER BY c.category, w.warehouse;','Intermediate')])

m=module('JOIN Cardinality and Existence')
lesson(m,'Self joins and hierarchical links','A self join gives the same table two aliases so one row can refer to another row.','Employees and managers share the same row structure but play different roles in a report.','Join employee.manager_id to manager.id. Use LEFT JOIN when the top-level employee has no manager.','Unqualified column names become ambiguous when both aliases have the same columns.',[
 task('Manager names','Return employee id, employee name as employee, and manager name as manager, including the top-level employee; order by employee id.','SELECT e.id, e.name AS employee, m.name AS manager FROM employees e LEFT JOIN employees m ON m.id = e.manager_id ORDER BY e.id;','Intermediate'),
 task('Higher paid than manager','Return employee id and name for employees earning more than their direct manager, ordered by employee id.','SELECT e.id, e.name FROM employees e JOIN employees m ON m.id = e.manager_id WHERE e.salary > m.salary ORDER BY e.id;','Intermediate'),
 task('Coworker pairs','Return e1.id as first_id and e2.id as second_id for each distinct pair in the same department, with first_id less than second_id; order both IDs.','SELECT e1.id AS first_id, e2.id AS second_id FROM employees e1 JOIN employees e2 ON e1.department = e2.department AND e1.id < e2.id ORDER BY first_id, second_id;','Advanced')])
lesson(m,'Multi-table joins and fan-out','Join cardinality describes how many rows match each source row. One-to-many joins repeat the one-side values.','Line-level revenue and order-level revenue are different measures and must be aggregated at the correct grain.','Join each relationship once. Name the intended result grain before aggregating. Pre-aggregate a many-side source when necessary.','Summing orders.total after joining multiple lines counts an order total repeatedly. DISTINCT is not a general repair for an incorrect join.',[
 task('Readable order lines','Return order_id, customer name as customer, product name as product, quantity, and line_total for lines with known customers; order by order_id and product_id.','SELECT o.id AS order_id, c.name AS customer, p.name AS product, i.quantity, i.quantity * i.unit_price AS line_total FROM orders o JOIN customers c ON c.id = o.customer_id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id ORDER BY o.id, p.id;','Intermediate'),
 task('Paid category revenue','Return category and revenue from paid order lines, ordered by category.','SELECT p.category, sum(i.quantity * i.unit_price) AS revenue FROM products p JOIN order_items i ON i.product_id = p.id JOIN orders o ON o.id = i.order_id WHERE o.status = \'paid\' GROUP BY p.category ORDER BY p.category;','Advanced'),
 task('Count orders at the customer grain','Return customer_id, distinct order_count, and line_count for known customers with order lines, ordered by customer_id.','SELECT o.customer_id, count(DISTINCT o.id) AS order_count, count(*) AS line_count FROM orders o JOIN order_items i ON i.order_id = o.id WHERE o.customer_id IS NOT NULL GROUP BY o.customer_id ORDER BY o.customer_id;','Advanced')])
lesson(m,'EXISTS, NOT EXISTS, and anti-joins','EXISTS checks whether a subquery produces at least one row. NOT EXISTS checks that it produces none.','Existence questions should not multiply the output when many matches exist.','A correlated subquery refers to the current outer row. EXISTS does not care which columns the inner SELECT returns.','NOT IN is unsafe with nullable subquery values unless NULL is handled explicitly.',[
 task('Customers who ordered','Return customer id and name for customers with at least one order, ordered by id.','SELECT c.id, c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id) ORDER BY c.id;','Intermediate'),
 task('Customers without orders','Return customer id and name for customers with no orders, ordered by id.','SELECT c.id, c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id) ORDER BY c.id;','Intermediate'),
 task('Products never in paid orders','Return product id and name for products with no line in any paid order, ordered by product id.','SELECT p.id, p.name FROM products p WHERE NOT EXISTS (SELECT 1 FROM order_items i JOIN orders o ON o.id = i.order_id WHERE i.product_id = p.id AND o.status = \'paid\') ORDER BY p.id;','Advanced')])

m=module('Subqueries and Derived Tables')
lesson(m,'Scalar subqueries','A scalar subquery supplies one value. Zero rows produce NULL; more than one row is an error.','One measure can be compared against a dynamically calculated benchmark.','Put the SELECT in parentheses where a value is expected. Aggregates without grouping are a common way to guarantee one row.','Do not assume a filter returns only one row unless a key or aggregate guarantees it.',[
 task('Above average prices','Return id, name, and price for products priced above the overall average, ordered by id.','SELECT id, name, price FROM products WHERE price > (SELECT avg(price) FROM products) ORDER BY id;','Intermediate'),
 task('Largest orders','Return id and total for all orders tied for the maximum total, ordered by id.','SELECT id, total FROM orders WHERE total = (SELECT max(total) FROM orders) ORDER BY id;','Intermediate'),
 task('Share of catalog stock','Return id and stock_share equal to stock divided by total catalog stock, rounded to four decimal places; order by id.','SELECT id, round(stock::numeric / NULLIF((SELECT sum(stock) FROM products),0),4) AS stock_share FROM products ORDER BY id;','Advanced')])
lesson(m,'Correlated subqueries','A correlated subquery depends on values from the outer query row.','A benchmark may need to be specific to each product category or employee department.','The inner query uses an outer alias. PostgreSQL may transform or repeatedly execute the operation depending on the plan.','A missing correlation condition silently changes a per-group question into a global one.',[
 task('Above category average','Return product id, name, and price for products above their own category average, ordered by id.','SELECT p.id, p.name, p.price FROM products p WHERE p.price > (SELECT avg(p2.price) FROM products p2 WHERE p2.category = p.category) ORDER BY p.id;','Advanced'),
 task('Department salary benchmark','Return employee id, name, and salary for employees above their department average, ordered by id.','SELECT e.id, e.name, e.salary FROM employees e WHERE e.salary > (SELECT avg(e2.salary) FROM employees e2 WHERE e2.department = e.department) ORDER BY e.id;','Advanced'),
 task('Order count per customer via subquery','Return customer id and order_count using a correlated count, including zero counts, ordered by id.','SELECT c.id, (SELECT count(*) FROM orders o WHERE o.customer_id = c.id) AS order_count FROM customers c ORDER BY c.id;','Intermediate')])
lesson(m,'Derived tables and LATERAL','A derived table is a subquery in FROM. LATERAL lets that subquery refer to preceding FROM sources.','Each customer may need a small related result such as their most recent order.','Alias every derived table for clarity. LEFT JOIN LATERAL ... ON true preserves outer rows with no inner result.','ORDER BY inside a subquery does not establish the final output order. Add a top-level ORDER BY.',[
 task('Average customer order counts','Return average_orders, rounded to two decimals, from counts grouped by non-NULL customer_id.','SELECT round(avg(order_count),2) AS average_orders FROM (SELECT customer_id, count(*) AS order_count FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id) counts;','Advanced'),
 task('Latest customer order','Return customer_id, latest_order_id, and ordered_on for every customer, choosing latest ordered_on then highest order id. Sort by customer_id.','SELECT c.id AS customer_id, latest.id AS latest_order_id, latest.ordered_on FROM customers c LEFT JOIN LATERAL (SELECT o.id, o.ordered_on FROM orders o WHERE o.customer_id = c.id ORDER BY o.ordered_on DESC, o.id DESC LIMIT 1) latest ON true ORDER BY c.id;','Advanced'),
 task('Top two per category','Return category, id, and price for the two highest priced products in each category, breaking price ties by id. Order category then price descending then id.','SELECT c.category, p.id, p.price FROM (SELECT DISTINCT category FROM products) c CROSS JOIN LATERAL (SELECT id, price FROM products p WHERE p.category = c.category ORDER BY price DESC, id LIMIT 2) p ORDER BY c.category, p.price DESC, p.id;','Advanced')])

m=module('CTEs and Set Operations')
lesson(m,'Common table expressions','A common table expression, or CTE, names a query for use within a larger statement.','Named stages make a complicated reporting calculation easier to reason about.','WITH name AS (...) introduces a CTE before the main query. PostgreSQL can fold some CTEs into the parent query; MATERIALIZED and NOT MATERIALIZED influence that behavior.','A CTE is not automatically a persisted table or always an optimization barrier.',[
 task('Name paid orders','Use a CTE to return id and total for paid orders over 50, ordered by id.','WITH paid AS (SELECT id, total FROM orders WHERE status = \'paid\') SELECT id, total FROM paid WHERE total > 50 ORDER BY id;','Intermediate'),
 task('Customer spend stage','Return customer_id and spend for known customers with paid spend at least 100, ordered by customer_id; structure the aggregation as a CTE.','WITH spending AS (SELECT customer_id, sum(total) AS spend FROM orders WHERE status = \'paid\' AND customer_id IS NOT NULL GROUP BY customer_id) SELECT customer_id, spend FROM spending WHERE spend >= 100 ORDER BY customer_id;','Intermediate'),
 task('Above-average category revenue','Return category and revenue for categories whose paid line revenue exceeds the mean category revenue, ordered by category.','WITH category_sales AS (SELECT p.category, sum(i.quantity*i.unit_price) AS revenue FROM products p JOIN order_items i ON i.product_id=p.id JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' GROUP BY p.category) SELECT category, revenue FROM category_sales WHERE revenue > (SELECT avg(revenue) FROM category_sales) ORDER BY category;','Advanced')])
lesson(m,'UNION and UNION ALL','UNION combines compatible results and removes duplicates. UNION ALL preserves every input row.','Data from separate segments can be combined using the same output contract.','Each branch needs the same number of columns and compatible data types. The first branch determines result column names.','UNION does not guarantee branch order. Removing duplicates can hide a data-quality issue or cost extra work.',[
 task('Unique places','Return city as place for known customer cities combined with inventory warehouses, removing duplicates and sorting by place.','SELECT city AS place FROM customers WHERE city IS NOT NULL UNION SELECT warehouse FROM inventory ORDER BY place;','Intermediate'),
 task('All known cities twice','Return each non-NULL city occurrence twice using UNION ALL, sorted by city; keep duplicates.','SELECT city FROM customers WHERE city IS NOT NULL UNION ALL SELECT city FROM customers WHERE city IS NOT NULL ORDER BY city;','Intermediate'),
 task('Unified activity amounts','Return source and amount for paid order totals (source order) and all booking charges (source booking), preserving all rows; order by source then amount.','SELECT \'order\' AS source, total AS amount FROM orders WHERE status=\'paid\' UNION ALL SELECT \'booking\', (check_out-check_in)*nightly_rate FROM bookings ORDER BY source, amount;','Advanced')])
lesson(m,'INTERSECT and EXCEPT','INTERSECT keeps values present in both results. EXCEPT keeps values in the first result but not the second.','Set operations express overlap and difference directly.','The default forms remove duplicates; ALL forms retain multiplicities according to the operation. INTERSECT binds more tightly than UNION and EXCEPT.','NULLs participate in set duplicate comparison. Set difference is different from a nullable NOT IN predicate.',[
 task('Customers both paid and pending','Return customer_id values having both paid and pending orders, excluding NULL, ordered by customer_id.','SELECT customer_id FROM orders WHERE status=\'paid\' AND customer_id IS NOT NULL INTERSECT SELECT customer_id FROM orders WHERE status=\'pending\' AND customer_id IS NOT NULL ORDER BY customer_id;','Intermediate'),
 task('Customers with no orders via sets','Return customer id as id for customers absent from non-NULL order customer IDs, ordered by id.','SELECT id FROM customers EXCEPT SELECT customer_id FROM orders WHERE customer_id IS NOT NULL ORDER BY id;','Intermediate'),
 task('Products bought but not paid','Return product_id values appearing in order_items but never in a paid order, ordered by product_id.','SELECT product_id FROM order_items EXCEPT SELECT i.product_id FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' ORDER BY product_id;','Advanced')])

m=module('INSERT, UPDATE, and DELETE')
lesson(m,'INSERT and RETURNING','INSERT adds rows. RETURNING exposes the values of the rows actually inserted.','A data-entry workflow needs to know what the database stored, including defaults and generated identifiers.','List target columns explicitly. VALUES supplies matching values; INSERT ... SELECT copies a query result.','Omitting a column uses its default or NULL. A key conflict raises an error unless ON CONFLICT handles it.',[
 task('Add a product','Insert product 50 named Ruler, category Office, price 3.50, stock 15. Return id, name, price, stock.','INSERT INTO products(id,name,category,price,stock) VALUES (50,\'Ruler\',\'Office\',3.50,15) RETURNING id,name,price,stock;','Intermediate',kind='modify',validation='SELECT id,name,category,price,stock FROM products ORDER BY id;'),
 task('Insert a customer','Insert customer 50 named Imani, city Rome, email imani@example.test, joined_on 2024-08-01, non-VIP.','INSERT INTO customers(id,name,city,email,joined_on) VALUES (50,\'Imani\',\'Rome\',\'imani@example.test\',DATE \'2024-08-01\');','Intermediate',kind='modify',validation='SELECT id,name,city,email,joined_on,vip FROM customers ORDER BY id;'),
 task('Archive paid order IDs','Create paid_archive(order_id integer PRIMARY KEY,total numeric(10,2)) and populate it from paid orders.','CREATE TABLE paid_archive(order_id integer PRIMARY KEY,total numeric(10,2)); INSERT INTO paid_archive SELECT id,total FROM orders WHERE status=\'paid\';','Advanced',kind='design',validation='SELECT order_id,total FROM paid_archive ORDER BY order_id;')])
lesson(m,'UPDATE with a precise scope','UPDATE changes matching rows. Expressions can use the old values in each row.','Stock adjustments, price changes, and status transitions are common business operations.','SET assigns columns; WHERE limits rows; RETURNING inspects changed rows. Test the WHERE predicate with SELECT first.','An omitted WHERE changes every row. UPDATE ... FROM with multiple source matches can choose an unpredictable source row.',[
 task('Restock empty products','Set stock to 10 only for products currently at zero.','UPDATE products SET stock=10 WHERE stock=0;','Intermediate',kind='modify',validation='SELECT id,stock FROM products ORDER BY id;'),
 task('Office price rise','Increase every Office product price by 10 percent, rounded to two decimals.','UPDATE products SET price=round(price*1.10,2) WHERE category=\'Office\';','Intermediate',kind='modify',validation='SELECT id,price FROM products ORDER BY id;'),
 task('Synchronize inventory','Set each product stock to the corresponding inventory quantity plus 2, leaving other columns unchanged.','UPDATE products p SET stock=i.quantity+2 FROM inventory i WHERE i.product_id=p.id;','Advanced',kind='modify',validation='SELECT id,name,category,price,stock FROM products ORDER BY id;')])
lesson(m,'DELETE and referential actions','DELETE removes matching rows. Foreign-key actions decide whether dependent rows prevent or follow a deletion.','Retention and correction workflows must preserve referential integrity.','Use DELETE FROM ... WHERE. DELETE ... USING can join supporting tables. TRUNCATE quickly empties whole tables with different locking and trigger behavior.','Deleting a parent row may fail when child rows exist. TRUNCATE is transactional in PostgreSQL but takes an ACCESS EXCLUSIVE lock.',[
 task('Remove unreferenced customers','Delete customers with no orders.','DELETE FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.id);','Intermediate',kind='modify',validation='SELECT id,name FROM customers ORDER BY id;'),
 task('Delete unused documents','Delete documents whose body does not contain the word SQL, ignoring case.','DELETE FROM documents WHERE body !~* \'SQL\';','Intermediate',kind='modify',validation='SELECT id,title,body FROM documents ORDER BY id;'),
 task('Empty event staging','Remove every row from events using TRUNCATE, preserving the table.','TRUNCATE events;','Intermediate',kind='modify',validation='SELECT count(*) AS remaining_events FROM events;')])

m=module('Upserts and Transactional Changes')
lesson(m,'ON CONFLICT and upserts','An upsert inserts a new row or updates an existing row when a unique constraint conflicts.','Idempotent import jobs can retry without creating duplicate primary keys.','ON CONFLICT(key) DO UPDATE uses EXCLUDED to refer to the proposed new row. DO NOTHING skips a conflict.','Only suitable unique or exclusion conflicts are handled. DO UPDATE needs a deterministic rule for merging values.',[
 task('Merge inventory count','Upsert product_id 1 in inventory with warehouse Central, quantity 60, updated_on 2024-08-01. Replace these values on conflict.','INSERT INTO inventory VALUES (1,\'Central\',60,DATE \'2024-08-01\') ON CONFLICT(product_id) DO UPDATE SET warehouse=EXCLUDED.warehouse,quantity=EXCLUDED.quantity,updated_on=EXCLUDED.updated_on;','Intermediate',kind='modify',validation='SELECT * FROM inventory ORDER BY product_id;'),
 task('Keep the original customer','Insert two proposed customers: id 1, Replacement, Rome, replacement@example.test, 2024-08-01; and id 50, Tari, Rome, tari@example.test, 2024-08-01. On an id conflict keep the existing row; insert the new row.','INSERT INTO customers(id,name,city,email,joined_on) VALUES (1,\'Replacement\',\'Rome\',\'replacement@example.test\',DATE \'2024-08-01\'),(50,\'Tari\',\'Rome\',\'tari@example.test\',DATE \'2024-08-01\') ON CONFLICT(id) DO NOTHING;','Intermediate',kind='modify',validation='SELECT * FROM customers ORDER BY id;'),
 task('Accumulate stock on conflict','Upsert inventory row for product 2, warehouse North, quantity 5, date 2024-08-01. On conflict add 5 to existing quantity and update updated_on, preserving warehouse.','INSERT INTO inventory VALUES(2,\'North\',5,DATE \'2024-08-01\') ON CONFLICT(product_id) DO UPDATE SET quantity=inventory.quantity+EXCLUDED.quantity,updated_on=EXCLUDED.updated_on;','Advanced',kind='modify',validation='SELECT * FROM inventory ORDER BY product_id;')])
lesson(m,'Transactions and savepoints','A transaction makes a sequence of changes succeed or fail as one unit. A savepoint marks a point that can be rolled back inside it.','A transfer must debit one account and credit another without exposing half a transfer.','BEGIN starts; COMMIT keeps changes; ROLLBACK discards them. SAVEPOINT and ROLLBACK TO SAVEPOINT allow partial recovery. Each submitted practice run uses a fresh isolated database.','After an error, a transaction is aborted until rolled back. Do not catch an error and continue as if earlier work committed.',[
 task('Transfer funds atomically','Transfer 100 from account 1 to account 2 in one explicit transaction.','BEGIN; UPDATE accounts SET balance=balance-100 WHERE id=1; UPDATE accounts SET balance=balance+100 WHERE id=2; COMMIT;','Intermediate',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;'),
 task('Cancel a draft adjustment','Begin a transaction, add 50 to account 1, then roll back the change.','BEGIN; UPDATE accounts SET balance=balance+50 WHERE id=1; ROLLBACK;','Intermediate',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;'),
 task('Recover at a savepoint','In a transaction add 10 to account 1, create a savepoint, add another 100, roll back only the second addition, and commit.','BEGIN; UPDATE accounts SET balance=balance+10 WHERE id=1; SAVEPOINT before_extra; UPDATE accounts SET balance=balance+100 WHERE id=1; ROLLBACK TO SAVEPOINT before_extra; COMMIT;','Advanced',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;')])
lesson(m,'Data-changing CTEs','A data-changing CTE can use RETURNING rows as input to another operation in the same statement.','Moving rows into an audit table can be expressed with one statement and a clear data flow.','A modifying WITH query executes once. Its RETURNING output is the relation visible to the rest of the statement. Sibling statements share one snapshot.','Do not rely on the physical execution order of sibling modifying CTEs or update the same row twice within one statement.',[
 task('Capture updated prices','Use an UPDATE CTE to reduce Home product prices by 1 and return id and new price, ordered by id.','WITH changed AS (UPDATE products SET price=price-1 WHERE category=\'Home\' RETURNING id,price) SELECT id,price FROM changed ORDER BY id;','Advanced',kind='modify',validation='SELECT id,price FROM products ORDER BY id;'),
 task('Archive deleted documents','Create document_archive(id integer PRIMARY KEY,title text). Move documents without SQL in body (case-insensitive) into the archive using DELETE RETURNING.','CREATE TABLE document_archive(id integer PRIMARY KEY,title text); WITH removed AS (DELETE FROM documents WHERE body !~* \'SQL\' RETURNING id,title) INSERT INTO document_archive SELECT id,title FROM removed;','Advanced',kind='modify',validation='SELECT \'live\' AS location,id,title FROM documents UNION ALL SELECT \'archive\',id,title FROM document_archive ORDER BY location,id;'),
 task('Insert and inspect one row','Insert product 51 named Eraser, Office category, price 1.25, stock 30 through a CTE, then return id and name.','WITH added AS (INSERT INTO products(id,name,category,price,stock) VALUES(51,\'Eraser\',\'Office\',1.25,30) RETURNING id,name) SELECT id,name FROM added;','Advanced',kind='modify',validation='SELECT id,name,price,stock FROM products ORDER BY id;')])

m=module('PostgreSQL Data Types')
lesson(m,'Integers, decimals, text, and booleans','A data type defines which values a column accepts and which operations make sense. PostgreSQL has smallint, integer, bigint, numeric, text, and boolean types.','Choosing types prevents invalid data and makes calculations predictable.','INTEGER is exact within its range; NUMERIC stores exact decimals; TEXT stores variable-length text; BOOLEAN stores true, false, or NULL.','VARCHAR(n) limits characters rather than bytes. A boolean is not the text string true, even when casts can convert it.',[
 task('Type names','Return integer_type, decimal_type, text_type, and boolean_type using pg_typeof on 1, 1.5, the text x, and true. Cast each pg_typeof result to text.','SELECT pg_typeof(1)::text AS integer_type, pg_typeof(1.5)::text AS decimal_type, pg_typeof(\'x\'::text)::text AS text_type, pg_typeof(true)::text AS boolean_type;'),
 task('Boolean output','Return customer id and is_priority equal to vip OR city is London, with unknown results changed to false; order by id.','SELECT id, COALESCE(vip OR city=\'London\',false) AS is_priority FROM customers ORDER BY id;','Intermediate'),
 task('Format an identifier','Return id and label formed as product- followed by id as text, ordered by id.','SELECT id, \'product-\' || id::text AS label FROM products ORDER BY id;')])
lesson(m,'UUIDs and enums','A UUID is a 128-bit identifier. An enum is a type with a fixed ordered set of text labels.','Distributed identifiers and constrained business states can be represented with explicit database types.','Use uuid literals for known identifiers. CREATE TYPE ... AS ENUM defines labels; comparisons follow their declaration order. PostgreSQL 18 includes uuidv4() and uuidv7(), but generated values are nondeterministic.','An enum label is case-sensitive. Adding and removing labels has migration tradeoffs compared with a lookup table.',[
 task('Read a UUID','Return identifier containing 123e4567-e89b-12d3-a456-426614174000 as a uuid.','SELECT \'123e4567-e89b-12d3-a456-426614174000\'::uuid AS identifier;','Intermediate'),
 task('Create ordered states','Create enum delivery_state with labels queued, sent, delivered in that order. Create deliveries(id integer PRIMARY KEY,state delivery_state), insert (1,delivered),(2,queued),(3,sent).','CREATE TYPE delivery_state AS ENUM (\'queued\',\'sent\',\'delivered\'); CREATE TABLE deliveries(id integer PRIMARY KEY,state delivery_state); INSERT INTO deliveries VALUES(1,\'delivered\'),(2,\'queued\'),(3,\'sent\');','Intermediate',kind='design',validation='SELECT id,state::text AS state FROM deliveries ORDER BY state::delivery_state,id;'),
 task('UUID storage contract','Create request_log(request_id uuid PRIMARY KEY, note text NOT NULL) and insert a row with UUID 00000000-0000-0000-0000-000000000001 and note imported.','CREATE TABLE request_log(request_id uuid PRIMARY KEY,note text NOT NULL); INSERT INTO request_log VALUES(\'00000000-0000-0000-0000-000000000001\',\'imported\');','Advanced',kind='design',validation="SELECT request_id,note FROM request_log ORDER BY request_id;")])
lesson(m,'String functions and normalization','String functions transform or inspect text. Normalization means consistently representing values before matching or storing them.','External data often contains unwanted spaces or inconsistent case.','lower and upper change case; trim removes edge spaces; length counts characters; concat_ws joins known parts with a separator.','length counts characters, while octet_length counts bytes. Case folding and ordering depend on collation and locale.',[
 task('Normalize email labels','Return id and normalized_email as lowercase email for customers with a known email, ordered by id.','SELECT id, lower(email) AS normalized_email FROM customers WHERE email IS NOT NULL ORDER BY id;'),
 task('Human-readable labels','Return id and label joining name and city with a comma and space; skip a NULL city. Order by id.','SELECT id, concat_ws(\', \',name,city) AS label FROM customers ORDER BY id;'),
 task('Inspect name lengths','Return id, name, and name_length, ordered by longest name first and id ascending for ties.','SELECT id,name,length(name) AS name_length FROM customers ORDER BY name_length DESC,id;','Intermediate')])

m=module('Dates, Time, and Intervals')
lesson(m,'Dates and calendar arithmetic','DATE stores a calendar day. Subtracting two dates produces the number of elapsed days.','Booking charges, delivery delays, and customer tenure depend on consistent calendar rules.','Use typed literals such as DATE 2024-07-01 with quotes around the value. Adding an integer to a date shifts it by days.','Calendar months have different lengths. Age in calendar years and elapsed days answer different questions.',[
 task('Booking nights','Return booking id, guest, and nights as check_out minus check_in, ordered by id.','SELECT id,guest,check_out-check_in AS nights FROM bookings ORDER BY id;'),
 task('Shipment delays','Return order id and shipping_days for shipped orders, ordered by id.','SELECT id,shipped_on-ordered_on AS shipping_days FROM orders WHERE shipped_on IS NOT NULL ORDER BY id;'),
 task('Follow-up dates','Return order id and follow_up_on equal to seven days after ordered_on for pending orders, ordered by id.','SELECT id,ordered_on+7 AS follow_up_on FROM orders WHERE status=\'pending\' ORDER BY id;','Intermediate')])
lesson(m,'Timestamps and time zones','TIMESTAMP WITHOUT TIME ZONE stores local date and time fields. TIMESTAMPTZ stores an instant and displays it in the session time zone.','An instant needs an unambiguous interpretation when users live in different time zones.','AT TIME ZONE converts between a local timestamp and an instant using a named time zone. Prefer explicit zones in reports.','TIMESTAMPTZ does not retain the original zone name. A local time during a daylight-saving transition can be ambiguous or nonexistent.',[
 task('Extract event hours','Return event id and event_hour as an integer extracted from occurred_at, ordered by id.','SELECT id,EXTRACT(HOUR FROM occurred_at)::integer AS event_hour FROM events ORDER BY id;','Intermediate'),
 task('Convert a known instant','Return utc_time as the timestamp without time zone representing 2024-07-01 12:00:00+02 in UTC.','SELECT TIMESTAMPTZ \'2024-07-01 12:00:00+02\' AT TIME ZONE \'UTC\' AS utc_time;','Intermediate'),
 task('Display event times in Tokyo','Treat each occurred_at as a UTC local timestamp, convert it to Asia/Tokyo local time, and return id and tokyo_time ordered by id.','SELECT id,(occurred_at AT TIME ZONE \'UTC\') AT TIME ZONE \'Asia/Tokyo\' AS tokyo_time FROM events ORDER BY id;','Advanced')])
lesson(m,'Intervals, date_trunc, and time buckets','An interval represents a duration with month, day, and sub-day components. date_trunc rounds a timestamp down to a calendar boundary.','Time-series reports need consistent daily or monthly buckets and explicit interval semantics.','Group on date_trunc for calendar periods. Subtract timestamps for elapsed intervals. Use fixed reference dates in reproducible tests.','A day across daylight-saving transitions need not equal 24 hours. now() is fixed at transaction start; clock_timestamp() observes wall-clock time.',[
 task('Monthly order totals','Return month_start as a date and revenue as sum of total, ordered by month_start.','SELECT date_trunc(\'month\',ordered_on)::date AS month_start,sum(total) AS revenue FROM orders GROUP BY month_start ORDER BY month_start;','Intermediate'),
 task('Daily events','Return event_day as a date and event_count, ordered by event_day.','SELECT date_trunc(\'day\',occurred_at)::date AS event_day,count(*) AS event_count FROM events GROUP BY event_day ORDER BY event_day;','Intermediate'),
 task('Event gaps','Return event id and minutes_since_start as numeric minutes after 2024-07-01 00:00:00, ordered by id.','SELECT id,EXTRACT(EPOCH FROM (occurred_at-TIMESTAMP \'2024-07-01 00:00:00\'))/60 AS minutes_since_start FROM events ORDER BY id;','Advanced')])

m=module('Arrays and JSONB')
lesson(m,'Arrays and element operations','A PostgreSQL array stores an ordered collection of values of one element type. Arrays normally use one-based indexes.','A modest collection such as product tags can be useful, while relationships with their own attributes often need a separate table.','ARRAY[...] constructs an array; = ANY(array) tests membership; @> tests containment; cardinality counts elements; unnest expands rows.','An empty array differs from NULL. A NULL element affects membership logic. Avoid comma-separated text as a substitute for an array.',[
 task('USB products','Return id and name of products whose tags contain usb, ordered by id.','SELECT id,name FROM products WHERE \'usb\'=ANY(tags) ORDER BY id;','Intermediate'),
 task('Tag counts','Return id and tag_count using cardinality(tags), ordered by id.','SELECT id,cardinality(tags) AS tag_count FROM products ORDER BY id;','Intermediate'),
 task('Tag popularity','Expand product tags and return tag and product_count, ordered by product_count descending then tag.','SELECT t.tag,count(*) AS product_count FROM products p CROSS JOIN LATERAL unnest(p.tags) AS t(tag) GROUP BY t.tag ORDER BY product_count DESC,t.tag;','Advanced')])
lesson(m,'JSON and JSONB extraction','JSON stores JSON text; JSONB stores a decomposed representation that supports efficient operations and indexing.','Flexible attributes can coexist with relational columns when their structure genuinely varies.','-> returns JSON; ->> returns text; #>> extracts a nested path as text. Cast extracted text before numeric comparison.','JSON null differs from SQL NULL. JSONB removes insignificant whitespace and duplicate object keys, keeping the last value.',[
 task('Product colors','Return id and color from attributes for every product, ordered by id; missing color produces SQL NULL.','SELECT id,attributes->>\'color\' AS color FROM products ORDER BY id;','Intermediate'),
 task('Highly rated products','Return id and rating as numeric for products with a JSON rating at least 4.5, ordered by id.','SELECT id,(attributes->>\'rating\')::numeric AS rating FROM products WHERE (attributes->>\'rating\')::numeric>=4.5 ORDER BY id;','Intermediate'),
 task('Device conversion amounts','Return device and amount as sum of purchase payload amounts by device, ordered by device.','SELECT payload->>\'device\' AS device,sum((payload->>\'amount\')::numeric) AS amount FROM events WHERE kind=\'purchase\' GROUP BY device ORDER BY device;','Advanced')])
lesson(m,'JSONB containment and updates','JSONB operators can test structure and create modified documents. jsonb_set returns a new document with a path changed.','Attribute filters and small document updates can happen in SQL without fetching and rewriting entire application objects.','@> tests containment; ? tests a top-level key. jsonb_set takes a text-array path and a JSONB replacement value.','Containment is structural and type-sensitive: JSON number 2 differs from JSON string 2. Preserve relational constraints for critical shared facts.',[
 task('Blue product attributes','Return id and name for products whose attributes contain color blue, ordered by id.','SELECT id,name FROM products WHERE attributes @> \'{"color":"blue"}\'::jsonb ORDER BY id;','Intermediate'),
 task('Products with ratings','Return id and name for products whose attributes have a rating key, ordered by id.','SELECT id,name FROM products WHERE attributes ? \'rating\' ORDER BY id;','Intermediate'),
 task('Mark office products featured','Add or replace JSONB key featured with true for Office products, preserving all other attributes.','UPDATE products SET attributes=jsonb_set(attributes,\'{featured}\',\'true\'::jsonb,true) WHERE category=\'Office\';','Advanced',kind='modify',validation='SELECT id,attributes FROM products ORDER BY id;')])

m=module('Constraints and Table Design')
lesson(m,'Primary, foreign, and unique keys','Constraints are database-enforced rules. A primary key combines uniqueness and non-NULL; a foreign key requires a matching referenced key.','Rules must hold no matter which application writes data.','Declare constraints in CREATE TABLE or ALTER TABLE. A UNIQUE constraint ordinarily permits multiple NULLs; NULLS NOT DISTINCT changes that in PostgreSQL 15 and later.','A foreign key does not automatically create an index on the referencing columns. A nullable foreign key can represent an optional relationship.',[
 task('Design customer notes','Create customer_notes with id integer primary key, customer_id integer not null referencing customers(id), and body text not null. Insert (1,1,Call after 5).','CREATE TABLE customer_notes(id integer PRIMARY KEY,customer_id integer NOT NULL REFERENCES customers(id),body text NOT NULL); INSERT INTO customer_notes VALUES(1,1,\'Call after 5\');','Intermediate',kind='design',validation="SELECT c.column_name,c.data_type,c.is_nullable FROM information_schema.columns c WHERE c.table_schema=current_schema() AND c.table_name='customer_notes' ORDER BY c.ordinal_position;"),
 task('Add a unique product name rule','Add a UNIQUE constraint on products.name.','ALTER TABLE products ADD CONSTRAINT products_name_unique UNIQUE(name);','Intermediate',kind='design',validation="SELECT string_agg(a.attname,',' ORDER BY k.ordinality) AS columns FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY k(attnum,ordinality) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=k.attnum WHERE n.nspname=current_schema() AND t.relname='products' AND c.contype='u' GROUP BY c.oid ORDER BY columns;"),
 task('Require one optional alias','Create customer_alias(customer_id integer references customers(id), alias text unique nulls not distinct).','CREATE TABLE customer_alias(customer_id integer REFERENCES customers(id),alias text UNIQUE NULLS NOT DISTINCT);','Advanced',kind='design',validation="SELECT c.contype,i.indnullsnotdistinct FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace LEFT JOIN pg_index i ON i.indexrelid=c.conindid WHERE n.nspname=current_schema() AND t.relname='customer_alias' ORDER BY c.contype;")])
lesson(m,'CHECK, defaults, and referential actions','CHECK constrains a row expression. DEFAULT supplies a value for an omitted column. Referential actions define what happens when a referenced row changes.','Data rules such as positive quantities should be enforced at the place all writers share.','A CHECK passes when its expression is true or NULL, so combine it with NOT NULL when missing values are forbidden. ON DELETE CASCADE removes dependents.','A CHECK cannot safely maintain cross-row totals. Defaults are applied on insertion; they do not retroactively fill existing rows.',[
 task('Constrain a reservation quantity','Create reservations(id integer primary key, quantity integer not null default 1 check(quantity>0)), then insert only id=1.','CREATE TABLE reservations(id integer PRIMARY KEY,quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0)); INSERT INTO reservations(id) VALUES(1);','Intermediate',kind='design',validation='SELECT id,quantity FROM reservations ORDER BY id;'),
 task('Cascade draft lines','Create drafts(id integer primary key) and draft_lines(id integer primary key,draft_id integer references drafts(id) on delete cascade). Insert draft 1 and line (1,1), then delete draft 1.','CREATE TABLE drafts(id integer PRIMARY KEY); CREATE TABLE draft_lines(id integer PRIMARY KEY,draft_id integer REFERENCES drafts(id) ON DELETE CASCADE); INSERT INTO drafts VALUES(1); INSERT INTO draft_lines VALUES(1,1); DELETE FROM drafts WHERE id=1;','Advanced',kind='design',validation='SELECT count(*) AS remaining_lines FROM draft_lines;'),
 task('Add a promotion default','Add products.promoted boolean NOT NULL DEFAULT false.','ALTER TABLE products ADD COLUMN promoted boolean NOT NULL DEFAULT false;','Intermediate',kind='design',validation='SELECT id,promoted FROM products ORDER BY id;')])
lesson(m,'Identity columns and sequences','An identity column obtains values from a sequence. A sequence generates numbers independently of ordinary row transaction rollback.','Automatic identifiers reduce coordination between concurrent writers.','GENERATED ALWAYS AS IDENTITY rejects ordinary explicit values; BY DEFAULT allows them. RETURNING retrieves generated values.','Sequences can have gaps after rollbacks or failed inserts. A generated number is not a reliable count or chronology.',[
 task('Create an identity log','Create activity_log with id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY and message text not null; insert Started then Finished.','CREATE TABLE activity_log(id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,message text NOT NULL); INSERT INTO activity_log(message) VALUES(\'Started\'),(\'Finished\');','Intermediate',kind='design',validation='SELECT id,message FROM activity_log ORDER BY id;'),
 task('Use a named sequence','Create ticket_number starting at 100. Return two successive nextval calls as first_ticket and second_ticket.','CREATE SEQUENCE ticket_number START WITH 100; SELECT nextval(\'ticket_number\') AS first_ticket,nextval(\'ticket_number\') AS second_ticket;','Intermediate'),
 task('Allow imported identities','Create imported_log(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,message text). Insert explicit id 50 with message Legacy, then omit id for message New.','CREATE TABLE imported_log(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,message text); INSERT INTO imported_log VALUES(50,\'Legacy\'); INSERT INTO imported_log(message) VALUES(\'New\');','Advanced',kind='design',validation='SELECT id,message FROM imported_log ORDER BY id;')])

m=module('Normalization, Schemas, and Migrations')
lesson(m,'Normalization and relationship tables','Normalization separates facts according to what determines them. A many-to-many relationship normally needs a junction table.','A product name should be maintained once, rather than in every order line.','First identify entities and candidate keys, then place each attribute with the key that determines it. A junction table often has a composite key.','Normalization is not splitting every column into a new table. Denormalization should respond to measured needs and keep a clear source of truth.',[
 task('Design product favorites','Create favorites with customer_id referencing customers(id), product_id referencing products(id), and a composite primary key. Insert (1,3) and (2,1).','CREATE TABLE favorites(customer_id integer REFERENCES customers(id),product_id integer REFERENCES products(id),PRIMARY KEY(customer_id,product_id)); INSERT INTO favorites VALUES(1,3),(2,1);','Intermediate',kind='design',validation='SELECT customer_id,product_id FROM favorites ORDER BY customer_id,product_id;'),
 task('Detect repeated city facts','Return city and customer_count for known cities with more than one customer, ordered by city.','SELECT city,count(*) AS customer_count FROM customers WHERE city IS NOT NULL GROUP BY city HAVING count(*)>1 ORDER BY city;','Intermediate'),
 task('Build a normalized category list','Create categories(id integer primary key,name text not null unique). Populate deterministic IDs with row_number over alphabetically ordered distinct product categories.','CREATE TABLE categories(id integer PRIMARY KEY,name text NOT NULL UNIQUE); INSERT INTO categories SELECT row_number() OVER(ORDER BY category)::integer,category FROM (SELECT DISTINCT category FROM products) c;','Advanced',kind='design',validation='SELECT id,name FROM categories ORDER BY id;')])
lesson(m,'Schema namespaces and catalogs','A schema groups database objects in a namespace. System catalogs describe the database itself.','Namespaces avoid collisions; metadata makes tools and migrations inspectable.','Unqualified names are resolved through search_path. information_schema offers portable metadata, while pg_catalog exposes PostgreSQL details.','Putting writable untrusted schemas before trusted objects in search_path can be unsafe. Qualify names in security-sensitive functions.',[
 task('List customer columns','Return column_name and data_type for customers in the current schema, ordered by ordinal_position.','SELECT column_name,data_type FROM information_schema.columns WHERE table_schema=current_schema() AND table_name=\'customers\' ORDER BY ordinal_position;','Intermediate'),
 task('List primary-key columns','Return table_name and column_name for primary-key columns in the current schema, ordered by table name then key column position.','SELECT tc.table_name,kcu.column_name FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON kcu.constraint_catalog=tc.constraint_catalog AND kcu.constraint_schema=tc.constraint_schema AND kcu.constraint_name=tc.constraint_name WHERE tc.table_schema=current_schema() AND tc.constraint_type=\'PRIMARY KEY\' ORDER BY tc.table_name,kcu.ordinal_position;','Advanced'),
 task('List table names','Return table_name for base tables in the current schema, ordered alphabetically.','SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_type=\'BASE TABLE\' ORDER BY table_name;','Intermediate')])
lesson(m,'Safe schema migrations','A migration is a versioned change to database structure or data. A reliable migration preserves intended facts and can be verified.','Applications evolve; ad hoc manual edits are hard to reproduce or review.','Use explicit ALTER statements, backfill data, then add stronger constraints. Many PostgreSQL DDL operations are transactional, but locks and operation-specific restrictions still matter.','Adding a NOT NULL rule before backfilling existing NULLs fails. Large schema changes may require a staged deployment outside this practice dataset.',[
 task('Backfill a customer segment','Add customers.segment text, fill VIP rows with priority and other rows with standard, then require NOT NULL.','ALTER TABLE customers ADD COLUMN segment text; UPDATE customers SET segment=CASE WHEN vip THEN \'priority\' ELSE \'standard\' END; ALTER TABLE customers ALTER COLUMN segment SET NOT NULL;','Advanced',kind='modify',validation='SELECT id,segment FROM customers ORDER BY id;'),
 task('Rename a clear column','Rename products.stock to stock_units, preserving every value.','ALTER TABLE products RENAME COLUMN stock TO stock_units;','Intermediate',kind='design',validation='SELECT id,stock_units FROM products ORDER BY id;'),
 task('Add a reviewed timestamp','Add orders.reviewed_at timestamp without time zone, initially NULL for every row.','ALTER TABLE orders ADD COLUMN reviewed_at timestamp without time zone;','Intermediate',kind='design',validation='SELECT id,reviewed_at FROM orders ORDER BY id;')])

m=module('Window Function Foundations')
lesson(m,'OVER and PARTITION BY','A window function calculates over rows related to the current row while keeping each detail row.','You can show each employee beside a department benchmark without collapsing employees into groups.','OVER defines a window. PARTITION BY divides rows into independent sets. An aggregate with OVER becomes a window calculation.','GROUP BY reduces rows; a window usually preserves them. Window functions run after WHERE and grouping and cannot be filtered directly in WHERE.',[
 task('Department salary totals','Return id, department, salary, and department_total as a window sum of salary by department, ordered by id.','SELECT id,department,salary,sum(salary) OVER(PARTITION BY department) AS department_total FROM employees ORDER BY id;','Intermediate'),
 task('Share of category stock','Return id, category, and stock_share as stock divided by category stock total, rounded to four decimals, ordered by id.','SELECT id,category,round(stock::numeric/NULLIF(sum(stock) OVER(PARTITION BY category),0),4) AS stock_share FROM products ORDER BY id;','Advanced'),
 task('Order count on each detail row','Return id, customer_id, and customer_order_count as a window count by customer_id, ordered by id. Include the NULL customer partition.','SELECT id,customer_id,count(*) OVER(PARTITION BY customer_id) AS customer_order_count FROM orders ORDER BY id;','Intermediate')])
lesson(m,'ROW_NUMBER, RANK, and DENSE_RANK','ROW_NUMBER numbers rows; RANK gives equal values equal rank with gaps; DENSE_RANK gives equal ranks without gaps.','Leaderboards and top-N-per-group reports need an explicit policy for ties.','Place ordering inside OVER. Add a unique tie-breaker to ROW_NUMBER, but omit it from a ranking definition when equal measures should tie.','A final ORDER BY does not control the order inside a window. Adding id to RANK breaks ties that the business rule may want to preserve.',[
 task('Number category products','Return id, category, and position using row_number within each category ordered by price descending then id; order output by id.','SELECT id,category,row_number() OVER(PARTITION BY category ORDER BY price DESC,id) AS position FROM products ORDER BY id;','Intermediate'),
 task('Department salary ranks','Return id, department, salary_rank using rank and dense_salary_rank using dense_rank by salary descending within department; order by id.','SELECT id,department,rank() OVER(PARTITION BY department ORDER BY salary DESC) AS salary_rank,dense_rank() OVER(PARTITION BY department ORDER BY salary DESC) AS dense_salary_rank FROM employees ORDER BY id;','Advanced'),
 task('Two highest-paid per department','Return id, name, department, and salary for the first two employees per department ranked by salary descending then id, ordered by department then salary descending then id.','WITH ranked AS (SELECT *,row_number() OVER(PARTITION BY department ORDER BY salary DESC,id) AS rn FROM employees) SELECT id,name,department,salary FROM ranked WHERE rn<=2 ORDER BY department,salary DESC,id;','Advanced')])
lesson(m,'LAG, LEAD, and neighboring rows','LAG reads a preceding row; LEAD reads a following row in window order.','Comparisons to a previous event or order do not require a self join.','The default offset is one. An optional default value applies when the requested row is outside the partition. PostgreSQL uses RESPECT NULLS behavior.','A NULL previous value differs from having no previous row. Date ties need a deterministic ordering key.',[
 task('Previous order totals','Return id, customer_id, total, and previous_total using the previous order for the same customer ordered by ordered_on then id; output by id.','SELECT id,customer_id,total,lag(total) OVER(PARTITION BY customer_id ORDER BY ordered_on,id) AS previous_total FROM orders ORDER BY id;','Advanced'),
 task('Days to next order','Return id and days_to_next within each customer, ordered by ordered_on then id, with output by id.','SELECT id,lead(ordered_on) OVER(PARTITION BY customer_id ORDER BY ordered_on,id)-ordered_on AS days_to_next FROM orders ORDER BY id;','Advanced'),
 task('Compare employee salaries','Return id and salary_change as salary minus the prior salary in department order by hired_on then id; first row gets NULL. Order by id.','SELECT id,salary-lag(salary) OVER(PARTITION BY department ORDER BY hired_on,id) AS salary_change FROM employees ORDER BY id;','Advanced')])

m=module('Window Frames and Analytics')
lesson(m,'Running totals and explicit frames','A window frame selects a subset of the ordered partition for each current row. ROWS uses physical row positions; RANGE groups peers by ordering values.','Cumulative and moving metrics need clear boundaries, especially when dates repeat.','ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW produces a deterministic running total when the window has unique ordering.','The default ordered frame extends through peers. This can make a running total jump when multiple rows have the same sort value.',[
 task('Running paid revenue','Return id, ordered_on, and running_revenue for paid orders ordered by ordered_on then id; use an explicit ROWS frame and output in that order.','SELECT id,ordered_on,sum(total) OVER(ORDER BY ordered_on,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue FROM orders WHERE status=\'paid\' ORDER BY ordered_on,id;','Advanced'),
 task('Three-order moving mean','Return id and moving_average rounded to two decimals across the current and two preceding orders in date/id order; output in that order.','SELECT id,round(avg(total) OVER(ORDER BY ordered_on,id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS moving_average FROM orders ORDER BY ordered_on,id;','Advanced'),
 task('Customer running spend','Return id, customer_id, and running_spend from paid orders with known customers, partitioned by customer and ordered by date then id, output by id.','SELECT id,customer_id,sum(total) OVER(PARTITION BY customer_id ORDER BY ordered_on,id ROWS UNBOUNDED PRECEDING) AS running_spend FROM orders WHERE status=\'paid\' AND customer_id IS NOT NULL ORDER BY id;','Advanced')])
lesson(m,'FIRST_VALUE, LAST_VALUE, and NTILE','FIRST_VALUE and LAST_VALUE read frame endpoints. NTILE assigns ordered rows to a chosen number of buckets.','Analytical reports often need a baseline, an end-of-period value, or approximately equal-size segments.','Use an explicit frame through UNBOUNDED FOLLOWING when LAST_VALUE should see the end of the partition. NTILE divides rows, not value ranges.','The default LAST_VALUE frame usually ends at the current peer group, not the final row. NTILE can place equal values in different buckets.',[
 task('Most expensive category price','Return id and category_max using first_value(price) within category ordered by price descending then id, output by id.','SELECT id,first_value(price) OVER(PARTITION BY category ORDER BY price DESC,id) AS category_max FROM products ORDER BY id;','Advanced'),
 task('Final order total per customer','Return id and final_total using last_value(total) by customer ordered by date then id over the full partition; output by id.','SELECT id,last_value(total) OVER(PARTITION BY customer_id ORDER BY ordered_on,id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS final_total FROM orders ORDER BY id;','Advanced'),
 task('Salary quartiles','Return id and quartile from ntile(4) across all employees ordered by salary descending then id, output by id.','SELECT id,ntile(4) OVER(ORDER BY salary DESC,id) AS quartile FROM employees ORDER BY id;','Advanced')])
lesson(m,'DISTINCT ON and ordered selection','PostgreSQL DISTINCT ON keeps the first row for each set of key expressions. It is a PostgreSQL-specific alternative to some ranking queries.','Selecting one latest record per customer is common in operational reports.','DISTINCT ON expressions must match the leftmost ORDER BY expressions. Additional sort keys decide which row is kept.','Without a deterministic ordering, the chosen representative is unpredictable. DISTINCT ON is not part of portable standard SQL.',[
 task('Latest known-customer orders','Return customer_id, id as order_id, and ordered_on for the latest order per non-NULL customer, breaking date ties by highest id; order by customer_id.','SELECT DISTINCT ON(customer_id) customer_id,id AS order_id,ordered_on FROM orders WHERE customer_id IS NOT NULL ORDER BY customer_id,ordered_on DESC,id DESC;','Advanced'),
 task('Cheapest product by category','Return category, id, and price for the cheapest product per category, using smallest id on ties; order by category.','SELECT DISTINCT ON(category) category,id,price FROM products ORDER BY category,price,id;','Advanced'),
 task('Fix a latest-event query','Fix this query to return customer_id, id as event_id, and occurred_at for the latest event per customer, highest id breaking ties; order by customer_id.','SELECT DISTINCT ON(customer_id) customer_id,id AS event_id,occurred_at FROM events ORDER BY customer_id,occurred_at DESC,id DESC;','Advanced',kind='fix',starter='SELECT DISTINCT ON (customer_id) customer_id, id AS event_id, occurred_at\nFROM events\nORDER BY occurred_at DESC;')])

m=module('Views and Materialized Views')
lesson(m,'Views as named queries','A view is a stored query definition that behaves like a table when selected. Ordinary views do not store their result rows.','A named reporting interface can hide repetitive joins and centralize business definitions.','CREATE VIEW name AS query defines it. A later query can filter or aggregate the view. Privilege behavior needs deliberate design for shared production use.','An ORDER BY inside a view does not guarantee every caller result order. Views do not inherently make a slow query faster.',[
 task('Create a paid-order view','Create paid_orders returning id, customer_id, ordered_on, and total for paid orders.','CREATE VIEW paid_orders AS SELECT id,customer_id,ordered_on,total FROM orders WHERE status=\'paid\';','Intermediate',kind='design',validation='SELECT * FROM paid_orders ORDER BY id;'),
 task('Create product stock values','Create product_values with id, name, and stock_value equal to price times stock.','CREATE VIEW product_values AS SELECT id,name,price*stock AS stock_value FROM products;','Intermediate',kind='design',validation='SELECT * FROM product_values ORDER BY id;'),
 task('Compose a customer report','Create customer_spending returning customer_id and paid_spend for every customer, with zero for no paid orders.','CREATE VIEW customer_spending AS SELECT c.id AS customer_id,COALESCE(sum(o.total),0) AS paid_spend FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status=\'paid\' GROUP BY c.id;','Advanced',kind='design',validation='SELECT * FROM customer_spending ORDER BY customer_id;')])
lesson(m,'Materialized results and refresh','A materialized view stores a query result until it is refreshed.','Expensive read-heavy summaries can trade freshness for faster repeated access.','CREATE MATERIALIZED VIEW stores initial rows. REFRESH MATERIALIZED VIEW recomputes them. Concurrent refresh requires a qualifying unique index and an already-populated view.','A materialized view does not update automatically with its source tables. Refresh behavior and locking matter in production.',[
 task('Materialize category totals','Create category_snapshot with category and stock_units equal to sum of stock.','CREATE MATERIALIZED VIEW category_snapshot AS SELECT category,sum(stock) AS stock_units FROM products GROUP BY category;','Intermediate',kind='design',validation='SELECT * FROM category_snapshot ORDER BY category;'),
 task('Refresh a changed summary','Create stock_snapshot with product id and stock, increase product 1 stock by 5, then refresh the materialized view.','CREATE MATERIALIZED VIEW stock_snapshot AS SELECT id,stock FROM products; UPDATE products SET stock=stock+5 WHERE id=1; REFRESH MATERIALIZED VIEW stock_snapshot;','Advanced',kind='modify',validation='SELECT id,stock FROM stock_snapshot ORDER BY id;'),
 task('Prepare concurrent refresh','Create customer_totals with customer_id and sum(total) as total from non-NULL order customers, add a unique index on customer_id, and refresh concurrently.','CREATE MATERIALIZED VIEW customer_totals AS SELECT customer_id,sum(total) AS total FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id; CREATE UNIQUE INDEX customer_totals_key ON customer_totals(customer_id); REFRESH MATERIALIZED VIEW CONCURRENTLY customer_totals;','Advanced',kind='design',validation='SELECT * FROM customer_totals ORDER BY customer_id;')])
lesson(m,'Set-returning functions and generated series','A set-returning function supplies rows as a relation. generate_series creates sequences of numbers or time values.','Calendar reports need dates with no events as well as dates that appear in the data.','Use FROM generate_series(...) AS alias(column). LEFT JOIN facts to a generated calendar and count a non-NULL fact key.','Counting star after a calendar LEFT JOIN counts the placeholder row on empty days.',[
 task('Generate five numbers','Return n from 1 through 5 inclusive, ordered by n.','SELECT n FROM generate_series(1,5) AS s(n) ORDER BY n;'),
 task('Calendar with zero counts','Return day and order_count for every date from 2024-07-01 through 2024-07-07, including zero counts, ordered by day.','SELECT d.day::date AS day,count(o.id) AS order_count FROM generate_series(DATE \'2024-07-01\',DATE \'2024-07-07\',INTERVAL \'1 day\') d(day) LEFT JOIN orders o ON o.ordered_on=d.day::date GROUP BY d.day ORDER BY d.day;','Advanced'),
 task('Expand booking nights','Return booking_id and night for every occupied booking night (check-in inclusive, check-out exclusive), ordered by booking_id then night.','SELECT b.id AS booking_id,n.day::date AS night FROM bookings b CROSS JOIN LATERAL generate_series(b.check_in,b.check_out-1,INTERVAL \'1 day\') n(day) ORDER BY b.id,night;','Advanced')])

m=module('Functions, Procedures, and PLpgSQL')
lesson(m,'SQL functions and volatility','A SQL function packages a calculation or query behind a typed interface. Volatility describes how results may change.','Reusable business calculations benefit from explicit argument and result types.','CREATE FUNCTION lists arguments, RETURNS type, LANGUAGE sql, and a body. IMMUTABLE promises equal inputs always yield equal outputs; STABLE allows database reads within a statement snapshot.','A wrong IMMUTABLE label can produce incorrect optimized results. Avoid SECURITY DEFINER unless you deliberately need and secure its elevated privileges.',[
 task('Create a VAT calculation','Create add_vat(amount numeric) returning numeric, LANGUAGE sql IMMUTABLE, multiplying amount by 1.20 and rounding to two decimals.','CREATE FUNCTION add_vat(amount numeric) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT round(amount*1.20,2) $$;','Intermediate',kind='design',validation='SELECT id,add_vat(price) AS gross_price FROM products ORDER BY id;'),
 task('Create a customer order count function','Create customer_order_count(cid integer) returning bigint, LANGUAGE sql STABLE, counting orders for that customer.','CREATE FUNCTION customer_order_count(cid integer) RETURNS bigint LANGUAGE sql STABLE AS $$ SELECT count(*) FROM orders WHERE customer_id=cid $$;','Advanced',kind='design',validation='SELECT id,customer_order_count(id) AS order_count FROM customers ORDER BY id;'),
 task('Complete a text function','Complete product_label(pid integer) returning text to return the product name for the supplied ID; LANGUAGE sql STABLE.','CREATE FUNCTION product_label(pid integer) RETURNS text LANGUAGE sql STABLE AS $$ SELECT name FROM products WHERE id=pid $$;','Intermediate',kind='complete',starter='CREATE FUNCTION product_label(pid integer) RETURNS text\nLANGUAGE sql STABLE AS $$\n    -- Return the matching name\n$$;',validation='SELECT id,product_label(id) AS label FROM products ORDER BY id;')])
lesson(m,'PLpgSQL variables and control flow','PL/pgSQL adds variables, branches, loops, and exception handling to SQL functions.','Some server-side rules need several dependent decisions rather than one SQL expression.','A dollar-quoted body commonly contains DECLARE, BEGIN, statements, RETURN, and END. Assignment uses := and IF ends with END IF.','Prefer a set-based SQL operation when it expresses the rule clearly. Row-by-row loops can be much slower.',[
 task('Create a stock label function','Create stock_label(qty integer) returning text in PL/pgSQL: empty for 0, low for values below 10, otherwise ready.','CREATE FUNCTION stock_label(qty integer) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF qty=0 THEN RETURN \'empty\'; ELSIF qty<10 THEN RETURN \'low\'; ELSE RETURN \'ready\'; END IF; END $$;','Advanced',kind='design',validation='SELECT id,stock_label(stock) AS label FROM products ORDER BY id;'),
 task('Build a guarded ratio','Create safe_ratio(a numeric,b numeric) returning numeric in PL/pgSQL, NULL for b=0 and otherwise a/b rounded to two decimals.','CREATE FUNCTION safe_ratio(a numeric,b numeric) RETURNS numeric LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF b=0 THEN RETURN NULL; END IF; RETURN round(a/b,2); END $$;','Advanced',kind='design',validation='SELECT id,safe_ratio(price,stock) AS ratio FROM products ORDER BY id;'),
 task('Use a local variable','Create booking_charge(bid integer) returning numeric in PL/pgSQL. Read nights times nightly_rate for that booking into a local variable and return it.','CREATE FUNCTION booking_charge(bid integer) RETURNS numeric LANGUAGE plpgsql STABLE AS $$ DECLARE charge numeric; BEGIN SELECT (check_out-check_in)*nightly_rate INTO charge FROM bookings WHERE id=bid; RETURN charge; END $$;','Advanced',kind='design',validation='SELECT id,booking_charge(id) AS charge FROM bookings ORDER BY id;')])
lesson(m,'Procedures and CALL','A procedure is invoked with CALL and can perform operations without being used as a value expression.','A named server-side operation can define a controlled multi-step business action.','CREATE PROCEDURE declares arguments and a body. A function returns a value; a procedure has distinct invocation and transaction-control rules.','Transaction control inside a procedure is permitted only in specific top-level CALL contexts. The practice procedures leave transaction boundaries to their caller.',[
 task('Create a restock procedure','Create restock(pid integer,units integer) in PL/pgSQL that adds units to products.stock for pid; call it for product 1 with 7 units.','CREATE PROCEDURE restock(pid integer,units integer) LANGUAGE plpgsql AS $$ BEGIN UPDATE products SET stock=stock+units WHERE id=pid; END $$; CALL restock(1,7);','Advanced',kind='design',validation='SELECT id,stock FROM products ORDER BY id;'),
 task('Create a transfer procedure','Create transfer_funds(source_id integer,destination_id integer,amount numeric) in PL/pgSQL that debits source and credits destination. Call it to transfer 25 from account 1 to 3.','CREATE PROCEDURE transfer_funds(source_id integer,destination_id integer,amount numeric) LANGUAGE plpgsql AS $$ BEGIN UPDATE accounts SET balance=balance-amount WHERE id=source_id; UPDATE accounts SET balance=balance+amount WHERE id=destination_id; END $$; CALL transfer_funds(1,3,25);','Advanced',kind='design',validation='SELECT id,balance FROM accounts ORDER BY id;',explanation='Both updates belong to the CALL statement transaction. A production transfer also validates positive amounts, distinct existing accounts, permissions, idempotency, and a consistent row-lock order. This task isolates the procedure mechanism.'),
 task('Procedure for stale inventory dates','Create mark_inventory_checked(as_of date) in PL/pgSQL setting every inventory.updated_on to as_of. Call it with 2024-08-15.','CREATE PROCEDURE mark_inventory_checked(as_of date) LANGUAGE plpgsql AS $$ BEGIN UPDATE inventory SET updated_on=as_of; END $$; CALL mark_inventory_checked(DATE \'2024-08-15\');','Advanced',kind='design',validation='SELECT product_id,updated_on FROM inventory ORDER BY product_id;')])

m=module('Triggers and Full-Text Search')
lesson(m,'Row triggers and NEW','A trigger automatically runs a function in response to a table event. A row trigger sees NEW and/or OLD records.','Auditing or invariant maintenance sometimes must happen for every writer.','CREATE TRIGGER names timing, event, target table, row or statement scope, and the trigger function. BEFORE row triggers may modify and return NEW.','Hidden trigger work can surprise callers. A trigger that recursively updates its own table needs careful control.',[
 task('Normalize customer names on insert','Create a BEFORE INSERT row trigger on customers that trims NEW.name. Insert customer 60 with name surrounded by two spaces (Zara), joined_on 2024-08-01.','CREATE FUNCTION trim_customer_name() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.name:=trim(NEW.name); RETURN NEW; END $$; CREATE TRIGGER normalize_name BEFORE INSERT ON customers FOR EACH ROW EXECUTE FUNCTION trim_customer_name(); INSERT INTO customers(id,name,joined_on) VALUES(60,\'  Zara  \',DATE \'2024-08-01\');','Advanced',kind='design',validation='SELECT id,name FROM customers ORDER BY id;'),
 task('Stamp inventory updates','Create a BEFORE UPDATE row trigger on inventory setting NEW.updated_on to 2024-08-20. Update product 1 quantity to quantity+1.','CREATE FUNCTION stamp_inventory() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_on:=DATE \'2024-08-20\'; RETURN NEW; END $$; CREATE TRIGGER inventory_stamp BEFORE UPDATE ON inventory FOR EACH ROW EXECUTE FUNCTION stamp_inventory(); UPDATE inventory SET quantity=quantity+1 WHERE product_id=1;','Advanced',kind='design',validation='SELECT * FROM inventory ORDER BY product_id;'),
 task('Round inserted product prices','Create a BEFORE INSERT row trigger on products rounding NEW.price to one decimal place. Insert product 60, Clip, Office, 1.26, stock 5.','CREATE FUNCTION round_product_price() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.price:=round(NEW.price,1); RETURN NEW; END $$; CREATE TRIGGER product_round BEFORE INSERT ON products FOR EACH ROW EXECUTE FUNCTION round_product_price(); INSERT INTO products(id,name,category,price,stock) VALUES(60,\'Clip\',\'Office\',1.26,5);','Advanced',kind='design',validation='SELECT id,price FROM products ORDER BY id;')])
lesson(m,'Audit triggers and OLD values','An audit trigger records facts about a change, including the prior and new values.','A history table helps explain how important business data changed.','For UPDATE, OLD contains the previous row and NEW contains the proposed or stored row depending on timing. An AFTER trigger normally returns NULL because its return value is ignored.','Avoid auditing every column without a retention policy. Audit tables need their own permissions and integrity guarantees in production.',[
 task('Audit price changes','Create price_audit(product_id integer,old_price numeric,new_price numeric), an AFTER UPDATE OF price row trigger on products recording OLD and NEW prices, then add 2 to product 1 price.','CREATE TABLE price_audit(product_id integer,old_price numeric,new_price numeric); CREATE FUNCTION audit_price() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO price_audit VALUES(NEW.id,OLD.price,NEW.price); RETURN NULL; END $$; CREATE TRIGGER price_history AFTER UPDATE OF price ON products FOR EACH ROW EXECUTE FUNCTION audit_price(); UPDATE products SET price=price+2 WHERE id=1;','Advanced',kind='design',validation='SELECT product_id,old_price,new_price FROM price_audit ORDER BY product_id,old_price,new_price;'),
 task('Audit deleted events','Create deleted_events(id integer,kind text), an AFTER DELETE trigger on events that copies OLD.id and OLD.kind, then delete visit events.','CREATE TABLE deleted_events(id integer,kind text); CREATE FUNCTION audit_event_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO deleted_events VALUES(OLD.id,OLD.kind); RETURN NULL; END $$; CREATE TRIGGER event_deletion AFTER DELETE ON events FOR EACH ROW EXECUTE FUNCTION audit_event_delete(); DELETE FROM events WHERE kind=\'visit\';','Advanced',kind='design',validation='SELECT id,kind FROM deleted_events ORDER BY id;'),
 task('Audit new customers','Create customer_audit(customer_id integer,name text), an AFTER INSERT row trigger on customers that copies id and name, then insert customer 61, Yara, joined_on 2024-08-01.','CREATE TABLE customer_audit(customer_id integer,name text); CREATE FUNCTION audit_customer_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO customer_audit VALUES(NEW.id,NEW.name); RETURN NULL; END $$; CREATE TRIGGER customer_insertion AFTER INSERT ON customers FOR EACH ROW EXECUTE FUNCTION audit_customer_insert(); INSERT INTO customers(id,name,joined_on) VALUES(61,\'Yara\',DATE \'2024-08-01\');','Advanced',kind='design',validation='SELECT customer_id,name FROM customer_audit ORDER BY customer_id;')])
lesson(m,'Full-text documents and search queries','Full-text search converts documents into searchable lexemes and evaluates structured search queries.','Word-aware search handles stemming and stop words better than simple substring matching.','to_tsvector creates a document representation; plainto_tsquery parses ordinary search words; @@ tests a match. Choose an explicit configuration such as english.','A text-search configuration affects stemming and stop words. ILIKE and full-text search answer different questions.',[
 task('Find SQL documents','Return id and title for documents matching the English full-text search SQL, ordered by id.','SELECT id,title FROM documents WHERE to_tsvector(\'english\',body) @@ plainto_tsquery(\'english\',\'SQL\') ORDER BY id;','Intermediate'),
 task('Require both search words','Return id and title for documents matching English query relational databases, ordered by id.','SELECT id,title FROM documents WHERE to_tsvector(\'english\',body) @@ plainto_tsquery(\'english\',\'relational databases\') ORDER BY id;','Advanced'),
 task('Phrase search','Return id and title for documents matching the English phrase SQL queries, ordered by id.','SELECT id,title FROM documents WHERE to_tsvector(\'english\',body) @@ phraseto_tsquery(\'english\',\'SQL queries\') ORDER BY id;','Advanced')])

m=module('Index Types and Access Paths')
lesson(m,'B-tree, Hash, and selectivity','An index is an auxiliary data structure that can locate rows without scanning every table row. B-tree supports equality and ordered range lookups; Hash supports equality.','Selective lookups and ordered retrieval can become much faster, at the cost of space and write work.','CREATE INDEX names a table and key expressions. The planner chooses whether an index is worth using based on estimated costs and selectivity.','An index is not a promise of an index scan. Tiny learning tables often favor sequential scans, correctly.',[
 task('Index customer order history','Create a B-tree index named orders_customer_date on orders(customer_id,ordered_on).','CREATE INDEX orders_customer_date ON orders USING btree(customer_id,ordered_on);','Intermediate',kind='design',validation="SELECT am.amname,pg_get_indexdef(i.indexrelid,1,true) AS key1,pg_get_indexdef(i.indexrelid,2,true) AS key2 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE c.oid='orders_customer_date'::regclass;"),
 task('Build an equality index','Create a Hash index named customers_city_hash on customers(city).','CREATE INDEX customers_city_hash ON customers USING hash(city);','Intermediate',kind='design',validation="SELECT am.amname,pg_get_indexdef(i.indexrelid,1,true) AS key1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE c.oid='customers_city_hash'::regclass;"),
 task('Measure a predicate fraction','Return matching_rows and total_rows for products priced below 20; compute both in one scan.','SELECT count(*) FILTER(WHERE price<20) AS matching_rows,count(*) AS total_rows FROM products;','Intermediate')])
lesson(m,'GIN, GiST, and BRIN','GIN indexes components of compound values; GiST is a framework for strategies such as range overlap; BRIN summarizes block ranges.','Different query operators and data layouts need different index structures.','Choose the access method and operator class for the predicate. Core PostgreSQL supports GIN on arrays and JSONB, GiST on range types, and BRIN on suitable ordered scalar values.','An index type alone does not explain performance. Data correlation, operator support, table size, and write workload matter.',[
 task('Index JSON attributes','Create a GIN index named products_attributes_gin on products(attributes).','CREATE INDEX products_attributes_gin ON products USING gin(attributes);','Advanced',kind='design',validation="SELECT am.amname,pg_get_indexdef(i.indexrelid,1,true) AS key1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE c.oid='products_attributes_gin'::regclass;"),
 task('Index booking ranges','Create a GiST expression index named booking_dates_gist on daterange(check_in,check_out,\'[)\').','CREATE INDEX booking_dates_gist ON bookings USING gist(daterange(check_in,check_out,\'[)\'));','Advanced',kind='design',validation="SELECT am.amname,pg_get_indexdef(i.indexrelid,1,true) AS key1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE c.oid='booking_dates_gist'::regclass;"),
 task('Index chronological events','Create a BRIN index named events_time_brin on events(occurred_at).','CREATE INDEX events_time_brin ON events USING brin(occurred_at);','Advanced',kind='design',validation="SELECT am.amname,pg_get_indexdef(i.indexrelid,1,true) AS key1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am am ON am.oid=c.relam WHERE c.oid='events_time_brin'::regclass;")])
lesson(m,'Partial, expression, and covering indexes','A partial index covers rows satisfying a predicate. An expression index stores computed keys. INCLUDE adds non-key payload columns.','A workload may repeatedly query only pending orders or normalized email values.','The query predicate must imply the partial index predicate for use. Indexed functions must be immutable. INCLUDE can support index-only scans when visibility information permits.','Wrapping an indexed column in a different expression may prevent a matching access path. Extra included columns make the index larger.',[
 task('Index pending orders','Create orders_pending_date on orders(ordered_on) only where status is pending.','CREATE INDEX orders_pending_date ON orders(ordered_on) WHERE status=\'pending\';','Advanced',kind='design',validation="SELECT pg_get_indexdef(i.indexrelid,1,true) AS key1,pg_get_expr(i.indpred,i.indrelid) AS predicate FROM pg_index i WHERE i.indexrelid='orders_pending_date'::regclass;"),
 task('Index normalized email','Create customers_lower_email on customers(lower(email)).','CREATE INDEX customers_lower_email ON customers(lower(email));','Advanced',kind='design',validation="SELECT pg_get_indexdef('customers_lower_email'::regclass,1,true) AS key1;"),
 task('Cover customer order totals','Create orders_customer_cover on orders(customer_id) INCLUDE(total,ordered_on).','CREATE INDEX orders_customer_cover ON orders(customer_id) INCLUDE(total,ordered_on);','Advanced',kind='design',validation="SELECT i.indnkeyatts,i.indnatts,pg_get_indexdef(i.indexrelid,1,true) AS key1,pg_get_indexdef(i.indexrelid,2,true) AS payload1,pg_get_indexdef(i.indexrelid,3,true) AS payload2 FROM pg_index i WHERE i.indexrelid='orders_customer_cover'::regclass;")])

m=module('EXPLAIN and Query Optimization')
lesson(m,'Reading EXPLAIN plans','EXPLAIN displays the execution plan PostgreSQL intends to use. Plan nodes form a tree of operations.','Performance work starts by finding where rows are scanned, joined, sorted, or aggregated.','Read the tree from children toward parents. Estimated rows and cost are planner estimates; cost units are not milliseconds.','A sequential scan is not automatically a defect, especially on a small table. Never infer real latency from estimated cost alone.',[
 task('Inspect a filtered scan','Return the EXPLAIN plan for SELECT id,name FROM products WHERE price>50, with COSTS OFF.','EXPLAIN (COSTS OFF) SELECT id,name FROM products WHERE price>50;','Intermediate',kind='plan',explanation='The plan reveals how the predicate is applied. Costs are hidden for this structural exercise. A small table often uses a sequential scan.'),
 task('Inspect a sort','Return EXPLAIN with COSTS OFF for SELECT id,price FROM products ORDER BY price DESC,id.','EXPLAIN (COSTS OFF) SELECT id,price FROM products ORDER BY price DESC,id;','Intermediate',kind='plan'),
 task('Inspect grouped revenue','Return EXPLAIN with COSTS OFF for SELECT status,sum(total) FROM orders GROUP BY status.','EXPLAIN (COSTS OFF) SELECT status,sum(total) FROM orders GROUP BY status;','Advanced',kind='plan')])
lesson(m,'EXPLAIN ANALYZE and actual work','EXPLAIN ANALYZE executes the statement and adds actual row and loop counts to the plan.','Comparing estimates with observed work reveals bad cardinality assumptions and expensive nodes.','ANALYZE means execute, not merely inspect. TIMING OFF suppresses per-node time; SUMMARY OFF suppresses variable timing summaries. Production analysis should also consider BUFFERS.','EXPLAIN ANALYZE on UPDATE or DELETE changes data. Use an explicit rollback where appropriate and consider function side effects.',[
 task('Observe actual filtered rows','Return EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) for SELECT id FROM products WHERE stock=0.','EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) SELECT id FROM products WHERE stock=0;','Advanced',kind='plan'),
 task('Observe limit work','Return EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) for SELECT id FROM orders ORDER BY id LIMIT 3.','EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) SELECT id FROM orders ORDER BY id LIMIT 3;','Advanced',kind='plan'),
 task('Observe aggregate work','Return EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) for SELECT count(*) FROM order_items.','EXPLAIN (ANALYZE, TIMING OFF, SUMMARY OFF, COSTS OFF) SELECT count(*) FROM order_items;','Advanced',kind='plan')])
lesson(m,'Rewrite queries without changing meaning','Optimization preserves a query result while reducing unnecessary work. The correct grain, predicates, and join structure matter before index changes.','A faster wrong report is still wrong. Alternative SQL is valuable when its meaning is established.','Filter early when semantics permit, select only needed columns, and avoid repeated work. Compare actual plans on representative data.','Moving a predicate across an outer join can change results. A timing result on eight rows says little about production scale.',[
 task('Repair an accidental inner join','Fix the starter to return customer_id and paid_count for every customer including zero, ordered by customer_id.','SELECT c.id AS customer_id,count(o.id) AS paid_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status=\'paid\' GROUP BY c.id ORDER BY c.id;','Advanced',kind='fix',starter='SELECT c.id AS customer_id, count(o.id) AS paid_count\nFROM customers c LEFT JOIN orders o ON o.customer_id=c.id\nWHERE o.status=\'paid\'\nGROUP BY c.id ORDER BY c.id;'),
 task('Replace a duplicating join with existence','Return id and name once for each customer with a paid order, ordered by id.','SELECT c.id,c.name FROM customers c WHERE EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status=\'paid\') ORDER BY c.id;','Advanced',kind='fix',starter='SELECT c.id,c.name\nFROM customers c JOIN orders o ON o.customer_id=c.id\nWHERE o.status=\'paid\' ORDER BY c.id;'),
 task('Sargable date range','Return id and ordered_on for June 2024 using direct column range predicates rather than extracting the month, ordered by id.','SELECT id,ordered_on FROM orders WHERE ordered_on>=DATE \'2024-06-01\' AND ordered_on<DATE \'2024-07-01\' ORDER BY id;','Intermediate',kind='complete',starter='SELECT id, ordered_on FROM orders\nWHERE -- write a half-open date range\nORDER BY id;')])

m=module('Statistics and Maintenance')
lesson(m,'ANALYZE and planner statistics','ANALYZE samples a table to update statistics used for row-count and selectivity estimates.','The planner needs approximate distributions to choose useful join and scan strategies.','Statistics include row counts, distinct values, common values, and histograms. Extended statistics describe dependencies and combinations of columns.','Statistics are estimates and may be stale. More statistics are not a replacement for a correct query or appropriate indexes.',[
 task('Refresh product statistics','Run ANALYZE on products, then return category and product_count ordered by category.','ANALYZE products; SELECT category,count(*) AS product_count FROM products GROUP BY category ORDER BY category;','Intermediate'),
 task('Create extended statistics','Create statistics orders_status_customer with dependencies and ndistinct on orders.status and orders.customer_id, then ANALYZE orders.','CREATE STATISTICS orders_status_customer(dependencies,ndistinct) ON status,customer_id FROM orders; ANALYZE orders;','Advanced',kind='design',validation="SELECT s.stxname,s.stxkind::text AS kinds FROM pg_statistic_ext s JOIN pg_namespace n ON n.oid=s.stxnamespace WHERE n.nspname=current_schema() ORDER BY s.stxname;"),
 task('Measure skew explicitly','Return status, order_count, and share as status count divided by all orders rounded to four decimals, ordered by status.','SELECT status,count(*) AS order_count,round(count(*)::numeric/(SELECT count(*) FROM orders),4) AS share FROM orders GROUP BY status ORDER BY status;','Advanced')])
lesson(m,'VACUUM, MVCC cleanup, and visibility','PostgreSQL keeps old row versions for concurrent readers. VACUUM reclaims reusable space and maintains visibility information; ANALYZE updates statistics.','Updates and deletes do not immediately remove every old row version. Regular maintenance keeps a changing database healthy.','Ordinary VACUUM generally permits concurrent reads and writes. VACUUM FULL rewrites the table with stronger locking. Autovacuum performs routine maintenance in production.','Ordinary VACUUM does not normally shrink the table file to its minimum size. VACUUM cannot run inside a transaction block.',[
 task('Maintain product storage','Run VACUUM (ANALYZE) products as a standalone statement. The checker inspects the resulting row estimate and all-visible page information.','VACUUM (ANALYZE) products;','Intermediate',kind='modify',validation="SELECT reltuples::bigint AS estimated_rows,relallvisible>0 AS has_visible_pages FROM pg_class WHERE oid='products'::regclass;",explanation='VACUUM cannot share one simple-query message with other ordinary statements because that message creates an implicit transaction. Submit VACUUM by itself. The checker inspects its catalog effects. This checks observed maintenance state, rather than proving which maintenance command was used.'),
 task('Maintain document visibility','Run VACUUM documents as a standalone statement. Do not delete any documents. The checker inspects row estimates and visible-page metadata.','VACUUM documents;','Advanced',kind='modify',validation="SELECT reltuples::bigint AS estimated_rows,relallvisible>0 AS has_visible_pages FROM pg_class WHERE oid='documents'::regclass;",explanation='Ordinary VACUUM marks fully visible pages when safe and updates relation statistics. This isolated fixture has committed rows and no concurrent snapshots. Production visibility outcomes depend on concurrent activity. Maintenance is checked through observable catalog state.'),
 task('Inspect relation persistence','Return table_name and persistence as pg_class.relpersistence cast to text for the current schema base tables, ordered by table_name.','SELECT c.relname AS table_name,c.relpersistence::text AS persistence FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relkind=\'r\' ORDER BY c.relname;','Advanced')])
lesson(m,'Performance troubleshooting and evidence','A performance investigation separates query meaning, estimated work, actual work, and system conditions.','Changing random settings can mask a problem while creating another one.','Record the slow query and workload, inspect EXPLAIN, compare estimates with actual rows, check indexes and statistics, then measure a targeted change.','Caching, concurrent load, tiny fixtures, and planning overhead can distort timings. Never claim a speedup from one unrepresentative run.',[
 task('Find high-fan-out customers','Return customer_id and order_count for known customers, ordered by count descending then customer_id.','SELECT customer_id,count(*) AS order_count FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id ORDER BY order_count DESC,customer_id;','Intermediate'),
 task('Inspect an expensive result shape','Return category, line_count, and revenue for paid order lines, ordered by revenue descending then category.','SELECT p.category,count(*) AS line_count,sum(i.quantity*i.unit_price) AS revenue FROM products p JOIN order_items i ON i.product_id=p.id JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' GROUP BY p.category ORDER BY revenue DESC,p.category;','Advanced'),
 task('Identify repeated product prices','Return price and product_count only for repeated product prices, ordered by price.','SELECT price,count(*) AS product_count FROM products GROUP BY price HAVING count(*)>1 ORDER BY price;','Intermediate')])

m=module('Transactions, MVCC, and Concurrency')
lesson(m,'ACID and snapshot visibility','ACID means atomicity, consistency, isolation, and durability. MVCC lets readers use snapshots while writers create new row versions.','Concurrent users need useful views of data without seeing incomplete work.','At READ COMMITTED, each statement gets a new snapshot. REPEATABLE READ keeps a transaction snapshot; SERIALIZABLE can reject transactions to prevent serialization anomalies.','Isolation does not eliminate the need for constraints or retry logic. This single-session workspace demonstrates transaction syntax; observing races requires multiple sessions outside this release.',[
 task('Inspect default isolation','Return isolation_level from current_setting(transaction_isolation).','SELECT current_setting(\'transaction_isolation\') AS isolation_level;','Intermediate'),
 task('Commit a repeatable-read transfer','In an explicit REPEATABLE READ transaction, move 10 from account 1 to 2 and commit.','BEGIN ISOLATION LEVEL REPEATABLE READ; UPDATE accounts SET balance=balance-10 WHERE id=1; UPDATE accounts SET balance=balance+10 WHERE id=2; COMMIT;','Advanced',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;'),
 task('Rollback a serializable draft','Start a SERIALIZABLE transaction, reduce account 2 by 5, then roll it back.','BEGIN ISOLATION LEVEL SERIALIZABLE; UPDATE accounts SET balance=balance-5 WHERE id=2; ROLLBACK;','Advanced',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;')])
lesson(m,'Row locks, NOWAIT, and SKIP LOCKED','A row lock coordinates writers working on the same row. NOWAIT errors instead of waiting; SKIP LOCKED omits locked rows.','Transfers and worker queues need explicit concurrency rules.','SELECT ... FOR UPDATE locks selected rows until transaction end. Lock rows in a consistent order. The current workspace runs one learner operation at a time, so it cannot demonstrate an actual competing waiter.','SKIP LOCKED gives an inconsistent view suitable for queues, not ordinary financial reporting. Locks remain until transaction completion.',[
 task('Lock a stable account set','Return id and balance for accounts 1 and 2 ordered by id using FOR UPDATE.','SELECT id,balance FROM accounts WHERE id IN(1,2) ORDER BY id FOR UPDATE;','Intermediate'),
 task('Use NOWAIT on inventory','Return product_id and quantity for inventory quantities below 10 ordered by product_id using FOR UPDATE NOWAIT.','SELECT product_id,quantity FROM inventory WHERE quantity<10 ORDER BY product_id FOR UPDATE NOWAIT;','Advanced'),
 task('Claim one pending order','Return id and total for the oldest pending order by ordered_on then id, taking one row FOR UPDATE SKIP LOCKED.','SELECT id,total FROM orders WHERE status=\'pending\' ORDER BY ordered_on,id LIMIT 1 FOR UPDATE SKIP LOCKED;','Advanced')])
lesson(m,'Deadlocks, retries, and connection pooling','A deadlock occurs when transactions wait in a cycle. A connection pool reuses database sessions to control connection overhead.','Reliable applications retry transient failures and avoid overwhelming the server with unbounded connections.','Use consistent lock order and short transactions. Retry a whole transaction after deadlock or serialization failure using bounded backoff. Transaction pooling does not preserve arbitrary session state between transactions.','Do not retry only the last failed statement of an aborted transaction. Temporary tables and session-level settings may not survive transaction pooling as expected.',[
 task('Use consistent lock order','In one explicit transaction, lock account 1 then account 3 by selecting each FOR UPDATE, transfer 15 from 1 to 3, and commit.','BEGIN; SELECT id FROM accounts WHERE id=1 FOR UPDATE; SELECT id FROM accounts WHERE id=3 FOR UPDATE; UPDATE accounts SET balance=balance-15 WHERE id=1; UPDATE accounts SET balance=balance+15 WHERE id=3; COMMIT;','Advanced',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;'),
 task('Use a transaction-local setting','Start a transaction, SET LOCAL application_name to querycraft_practice, insert its value into a new table session_observation(value text), and commit.','BEGIN; SET LOCAL application_name=\'querycraft_practice\'; CREATE TABLE session_observation(value text); INSERT INTO session_observation SELECT current_setting(\'application_name\'); COMMIT;','Advanced',kind='design',validation='SELECT value FROM session_observation;'),
 task('Protect an invariant in a transfer','Transfer 20 from account 1 to 2 in one transaction, changing only those accounts and preserving the total balance.','BEGIN; UPDATE accounts SET balance=balance-20 WHERE id=1; UPDATE accounts SET balance=balance+20 WHERE id=2; COMMIT;','Advanced',kind='modify',validation='SELECT id,balance FROM accounts ORDER BY id;')])

m=module('Security and Permissions')
lesson(m,'Roles, ownership, and least privilege','A role is a database identity that can own objects and receive privileges. A login role can open sessions; a group role can collect permissions.','Applications should have only the capabilities their work requires.','GRANT gives privileges and REVOKE removes them. Object ownership includes powerful management rights. The practice role is deliberately not a superuser, role creator, or database creator.','Database privileges and host operating-system access are different boundaries. This app prohibits server administration and unrestricted extension installation.',[
 task('Inspect select permission','Return can_select containing whether current_user has SELECT privilege on products.','SELECT has_table_privilege(current_user,\'products\',\'SELECT\') AS can_select;','Intermediate'),
 task('Check administrative flags','Return is_superuser, can_create_roles, and can_create_databases from pg_roles for current_user; do not return the generated role name.','SELECT rolsuper AS is_superuser,rolcreaterole AS can_create_roles,rolcreatedb AS can_create_databases FROM pg_roles WHERE rolname=current_user;','Intermediate'),
 task('Remove public table access','Revoke ALL privileges on products from PUBLIC, preserving the current owner access.','REVOKE ALL ON products FROM PUBLIC;','Advanced',kind='design',validation="SELECT has_table_privilege(current_user,'products','SELECT') AS owner_can_select,COALESCE((SELECT bool_or(a.privilege_type='SELECT') FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid='products'::regclass AND a.grantee=0),false) AS public_can_select;")])
lesson(m,'SQL injection and parameterized queries','SQL injection happens when untrusted text is treated as SQL syntax. A parameterized query sends values separately from command structure.','A name containing a quote must remain data rather than changing the meaning of a query.','PostgreSQL prepared statements use $1, $2, and typed parameters. Client libraries provide binding APIs. SQL identifiers need separate safe composition rules; they cannot be bound as ordinary value parameters.','Escaping strings manually is fragile. Parameterization does not replace authorization or validate dynamic table names.',[
 task('Prepare a customer lookup','PREPARE lookup_customer(text) selecting id and name where name=$1 ordered by id; EXECUTE it for Ada.','PREPARE lookup_customer(text) AS SELECT id,name FROM customers WHERE name=$1 ORDER BY id; EXECUTE lookup_customer(\'Ada\');','Intermediate'),
 task('Bind a price threshold','PREPARE affordable(numeric) selecting id and price from products with price<$1 ordered by id; EXECUTE for 20.','PREPARE affordable(numeric) AS SELECT id,price FROM products WHERE price<$1 ORDER BY id; EXECUTE affordable(20);','Intermediate'),
 task('Keep hostile text as data','PREPARE exact_name(text) selecting customer id and name where name=$1 ordered by id. Execute with the literal text: Ada\' OR true --. The result must be empty.','PREPARE exact_name(text) AS SELECT id,name FROM customers WHERE name=$1 ORDER BY id; EXECUTE exact_name(\'Ada\'\' OR true --\');','Advanced')])
lesson(m,'Row-level security policies','Row-level security, or RLS, adds per-row access rules after ordinary table privileges.','Multi-tenant or restricted data views may need row rules enforced in the database.','ENABLE ROW LEVEL SECURITY activates policies. CREATE POLICY defines USING for visible rows and WITH CHECK for proposed rows. Owners normally bypass RLS unless FORCE ROW LEVEL SECURITY applies.','RLS is not a replacement for table privileges. Superusers and BYPASSRLS roles can bypass policies; views and security-definer functions require careful review.',[
 task('Restrict visible customers to VIPs','Enable and FORCE RLS on customers, create a SELECT policy using vip, then return id and name ordered by id.','ALTER TABLE customers ENABLE ROW LEVEL SECURITY; ALTER TABLE customers FORCE ROW LEVEL SECURITY; CREATE POLICY vip_only ON customers FOR SELECT USING(vip); SELECT id,name FROM customers ORDER BY id;','Advanced',kind='design',validation='SELECT id,name FROM customers ORDER BY id;'),
 task('Restrict products by category','Enable and FORCE RLS on products and create a SELECT policy allowing only Office products.','ALTER TABLE products ENABLE ROW LEVEL SECURITY; ALTER TABLE products FORCE ROW LEVEL SECURITY; CREATE POLICY office_only ON products FOR SELECT USING(category=\'Office\');','Advanced',kind='design',validation='SELECT id,name,category FROM products ORDER BY id;'),
 task('Protect low-balance accounts','Enable and FORCE RLS on accounts and create a SELECT policy showing balances at least 500.','ALTER TABLE accounts ENABLE ROW LEVEL SECURITY; ALTER TABLE accounts FORCE ROW LEVEL SECURITY; CREATE POLICY funded_accounts ON accounts FOR SELECT USING(balance>=500);','Advanced',kind='design',validation='SELECT id,owner,balance FROM accounts ORDER BY id;')])

m=module('Backup, Replication, and Operations')
lesson(m,'Logical backups and restore checks','A backup is a recoverable copy of data and the information needed to restore it. A copy of query rows alone is not a complete database backup.','Recovery must be tested before an accident, including schema, constraints, roles, and expected application behavior.','pg_dump makes a logical database backup; pg_restore reads archive formats. A production process also plans globals, retention, encryption, and point-in-time recovery. CLI backup tools are covered conceptually; this query workspace does not execute host commands.','A successful backup command does not prove restore works. COPY of one table does not preserve all database objects or cross-table consistency.',[
 task('Create a table-level data snapshot','Create account_snapshot AS SELECT id,owner,balance FROM accounts. This exercise copies rows only, not constraints or a full database.','CREATE TABLE account_snapshot AS SELECT id,owner,balance FROM accounts;','Intermediate',kind='design',validation='SELECT id,owner,balance FROM account_snapshot ORDER BY id;'),
 task('Verify restore totals','Return account_count and total_balance as a baseline for a restore check.','SELECT count(*) AS account_count,sum(balance) AS total_balance FROM accounts;','Intermediate'),
 task('Verify referential completeness','Return orphan_count as the count of non-NULL order customer IDs without a matching customer.','SELECT count(*) AS orphan_count FROM orders o WHERE o.customer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.id=o.customer_id);','Advanced')])
lesson(m,'WAL and replication concepts','Write-ahead logging, or WAL, records changes before data pages are persisted. Replication transfers changes to another server.','Recovery, read scaling, and high availability need durable change streams and clear failure policies.','Physical replication follows WAL at the storage level. Logical replication publishes row changes for selected tables. Replication lag and failover decisions affect freshness and data-loss risk. The bundled app uses one local primary and does not provision replicas.','A replica is not an independent historical backup: unwanted deletes can replicate too. Synchronous replication has latency and availability tradeoffs.',[
 task('Identify primary recovery state','Return in_recovery from pg_is_in_recovery(). The local practice server should be a primary.','SELECT pg_is_in_recovery() AS in_recovery;','Intermediate'),
 task('Find logical identity keys','Return table_name and key_column for primary keys of accounts and orders in the current schema, ordered by table_name then key ordinal.','SELECT tc.table_name,k.column_name AS key_column FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage k ON k.constraint_name=tc.constraint_name AND k.constraint_schema=tc.constraint_schema WHERE tc.table_schema=current_schema() AND tc.table_name IN(\'accounts\',\'orders\') AND tc.constraint_type=\'PRIMARY KEY\' ORDER BY tc.table_name,k.ordinal_position;','Advanced'),
 task('Build a stable reconciliation summary','Return status, row_count, and total_amount for orders, ordered by status, as a simple primary/replica reconciliation report.','SELECT status,count(*) AS row_count,sum(total) AS total_amount FROM orders GROUP BY status ORDER BY status;','Intermediate')])
lesson(m,'Operational troubleshooting','Operational troubleshooting connects symptoms to evidence from the database, application, and host.','Connection failures, blocked queries, stale statistics, and disk exhaustion need different remedies.','Check the error and SQLSTATE, confirm server reachability, inspect active work and locks with appropriate privileges, then address the specific cause. The learner role cannot administer this bundled server; reset the dataset or restart the engine through the app.','Do not terminate sessions or change global settings without understanding the workload. Avoid exposing credentials or customer data in logs.',[
 task('Validate a row-level business invariant','Return invalid_total_count for orders with negative total.','SELECT count(*) AS invalid_total_count FROM orders WHERE total<0;','Intermediate'),
 task('Find unsent paid orders','Return id and ordered_on for paid orders with NULL shipped_on, ordered by ordered_on then id.','SELECT id,ordered_on FROM orders WHERE status=\'paid\' AND shipped_on IS NULL ORDER BY ordered_on,id;','Intermediate'),
 task('Inspect available table constraints','Return table_name, constraint_type, and constraint_count for current-schema tables, ordered by table_name then constraint_type.','SELECT table_name,constraint_type,count(*) AS constraint_count FROM information_schema.table_constraints WHERE table_schema=current_schema() GROUP BY table_name,constraint_type ORDER BY table_name,constraint_type;','Advanced')])

m=module('Recursive Queries and Hierarchies')
lesson(m,'Recursive CTE anchors and steps','A recursive CTE starts with anchor rows and repeatedly applies a recursive term until no new rows remain.','Trees and graph paths have an unknown number of levels, which a fixed number of joins cannot express.','WITH RECURSIVE names the CTE. UNION ALL combines the anchor and recursive term. The recursive term joins the current working set to the next links.','A cycle can make recursion continue indefinitely. Depth limits and cycle detection need deliberate design.',[
 task('Generate recursively','Return n from 1 through 5 using a recursive CTE, ordered by n.','WITH RECURSIVE numbers(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<5) SELECT n FROM numbers ORDER BY n;','Intermediate'),
 task('Employee hierarchy depths','Return id, name, and depth for all employees reachable from manager_id NULL roots, with roots at depth 0, ordered by id.','WITH RECURSIVE tree AS (SELECT id,name,manager_id,0 AS depth FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id,e.name,e.manager_id,t.depth+1 FROM employees e JOIN tree t ON e.manager_id=t.id) SELECT id,name,depth FROM tree ORDER BY id;','Advanced'),
 task('All reports under Noor','Return id and name of all direct and indirect reports of employee 2, excluding employee 2, ordered by id.','WITH RECURSIVE reports AS (SELECT id,name FROM employees WHERE manager_id=2 UNION ALL SELECT e.id,e.name FROM employees e JOIN reports r ON e.manager_id=r.id) SELECT id,name FROM reports ORDER BY id;','Advanced')])
lesson(m,'Paths and cycle detection','A path records visited identifiers during recursion. It can support breadcrumbs and prevent revisiting a node.','Real graph data can contain cycles even when a business process expects a tree.','Append each new ID to an array and reject IDs already in the path. PostgreSQL also provides SEARCH and CYCLE clauses for recursive queries.','A depth limit is a safety guard, not proof that the graph has no cycle. UNION alone removes identical full rows, which may not stop paths whose depth changes.',[
 task('Build employee paths','Return id and path as an integer array from root to employee, ordered by id.','WITH RECURSIVE tree AS (SELECT id,manager_id,ARRAY[id] AS path FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id,e.manager_id,t.path||e.id FROM employees e JOIN tree t ON e.manager_id=t.id WHERE NOT e.id=ANY(t.path)) SELECT id,path FROM tree ORDER BY id;','Advanced'),
 task('Make readable breadcrumbs','Return id and breadcrumb joining hierarchy names with > surrounded by spaces, ordered by id.','WITH RECURSIVE tree AS (SELECT id,manager_id,name AS breadcrumb FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.id,e.manager_id,t.breadcrumb||\' > \'||e.name FROM employees e JOIN tree t ON e.manager_id=t.id) SELECT id,breadcrumb FROM tree ORDER BY id;','Advanced'),
 task('Traverse a cyclic graph safely','Use edges (1,2),(2,3),(3,1),(2,4), start node 1, and return distinct reachable node IDs including 1 as node, ordered by node. Prevent infinite recursion.','WITH RECURSIVE edges(a,b) AS (VALUES(1,2),(2,3),(3,1),(2,4)), walk(node) AS (SELECT 1 UNION SELECT e.b FROM walk w JOIN edges e ON e.a=w.node) SELECT node FROM walk ORDER BY node;','Advanced')])
lesson(m,'Recursive rollups','A recursive traversal can connect each ancestor with all descendants before aggregation.','Managers may need totals for their complete reporting subtree, not just direct reports.','Keep the ancestor ID fixed while recursively following children. Aggregate at the ancestor grain after traversal.','Adding each level subtotal recursively can double count. Decide whether the root employee is included in the requested total.',[
 task('Count every reporting subtree','Return manager_id and report_count for every employee, excluding themselves from their own report count, ordered by manager_id.','WITH RECURSIVE links AS (SELECT id AS manager_id,id AS employee_id FROM employees UNION ALL SELECT l.manager_id,e.id FROM links l JOIN employees e ON e.manager_id=l.employee_id) SELECT manager_id,count(*)-1 AS report_count FROM links GROUP BY manager_id ORDER BY manager_id;','Advanced'),
 task('Roll up salary budgets','Return leader_id and subtree_salary including each leader own salary plus all descendants, ordered by leader_id.','WITH RECURSIVE links AS (SELECT id AS leader_id,id AS employee_id FROM employees UNION ALL SELECT l.leader_id,e.id FROM links l JOIN employees e ON e.manager_id=l.employee_id) SELECT l.leader_id,sum(e.salary) AS subtree_salary FROM links l JOIN employees e ON e.id=l.employee_id GROUP BY l.leader_id ORDER BY l.leader_id;','Advanced'),
 task('Find leaf employees','Return id and name for employees with no direct reports, ordered by id.','SELECT e.id,e.name FROM employees e WHERE NOT EXISTS(SELECT 1 FROM employees child WHERE child.manager_id=e.id) ORDER BY e.id;','Intermediate')])

m=module('Advanced PostgreSQL Patterns')
lesson(m,'Ranges and overlap operators','A range value represents a set of ordered values with explicit inclusive or exclusive bounds. PostgreSQL has built-in date, timestamp, and numeric ranges.','Booking and scheduling rules are clearer when overlap is one typed operation.','daterange(start,end,\'[)\') includes check-in and excludes check-out. The && operator tests overlap; @> tests containment.','Adjacent half-open bookings need not overlap. Empty ranges and unbounded endpoints require deliberate interpretation.',[
 task('Bookings covering July 3','Return id and guest for bookings whose half-open date range contains 2024-07-03, ordered by id.','SELECT id,guest FROM bookings WHERE daterange(check_in,check_out,\'[)\') @> DATE \'2024-07-03\' ORDER BY id;','Intermediate'),
 task('Bookings overlapping a period','Return id and room for bookings overlapping 2024-07-03 inclusive through 2024-07-05 exclusive, ordered by id.','SELECT id,room FROM bookings WHERE daterange(check_in,check_out,\'[)\') && daterange(DATE \'2024-07-03\',DATE \'2024-07-05\',\'[)\') ORDER BY id;','Advanced'),
 task('Detect room conflicts','Return first_booking and second_booking IDs for overlapping bookings in the same room, each pair once with first ID smaller, ordered by both IDs.','SELECT a.id AS first_booking,b.id AS second_booking FROM bookings a JOIN bookings b ON a.room=b.room AND a.id<b.id AND daterange(a.check_in,a.check_out,\'[)\') && daterange(b.check_in,b.check_out,\'[)\') ORDER BY first_booking,second_booking;','Advanced')])
lesson(m,'Declarative partitioning','A partitioned table routes rows into child tables according to a partition key. Range partition upper bounds are exclusive.','Very large time-based datasets may benefit from pruning and partition lifecycle operations.','CREATE TABLE ... PARTITION BY declares a parent. CREATE TABLE ... PARTITION OF defines children and bounds. Unique constraints on a partitioned parent must include all partition key columns.','Partitioning is not a universal speed fix. Too many partitions add overhead, and a missing destination partition causes an insert error.',[
 task('Build quarterly event partitions','Create quarterly_events(id integer,event_day date not null) partitioned by RANGE(event_day); create q1_events for [2024-01-01,2024-04-01) and q2_events for [2024-04-01,2024-07-01). Insert (1,2024-03-31),(2,2024-04-01).','CREATE TABLE quarterly_events(id integer,event_day date NOT NULL) PARTITION BY RANGE(event_day); CREATE TABLE q1_events PARTITION OF quarterly_events FOR VALUES FROM(\'2024-01-01\') TO(\'2024-04-01\'); CREATE TABLE q2_events PARTITION OF quarterly_events FOR VALUES FROM(\'2024-04-01\') TO(\'2024-07-01\'); INSERT INTO quarterly_events VALUES(1,\'2024-03-31\'),(2,\'2024-04-01\');','Advanced',kind='design',validation='SELECT id,event_day,tableoid::regclass::text AS partition FROM quarterly_events ORDER BY id;'),
 task('Build category list partitions','Create categorized_stock(id integer,category text,quantity integer) partitioned by LIST(category), with office_stock for Office and other_stock as DEFAULT. Insert every products id,category,stock.','CREATE TABLE categorized_stock(id integer,category text,quantity integer) PARTITION BY LIST(category); CREATE TABLE office_stock PARTITION OF categorized_stock FOR VALUES IN(\'Office\'); CREATE TABLE other_stock PARTITION OF categorized_stock DEFAULT; INSERT INTO categorized_stock SELECT id,category,stock FROM products;','Advanced',kind='design',validation='SELECT id,category,quantity,tableoid::regclass::text AS partition FROM categorized_stock ORDER BY id;'),
 task('Partition a primary key correctly','Create dated_notes(id integer,note_day date,body text,PRIMARY KEY(id,note_day)) partitioned by RANGE(note_day), with all_notes DEFAULT partition. Insert (1,2024-07-01,Ready).','CREATE TABLE dated_notes(id integer,note_day date,body text,PRIMARY KEY(id,note_day)) PARTITION BY RANGE(note_day); CREATE TABLE all_notes PARTITION OF dated_notes DEFAULT; INSERT INTO dated_notes VALUES(1,\'2024-07-01\',\'Ready\');','Advanced',kind='design',validation='SELECT id,note_day,body FROM dated_notes ORDER BY id,note_day;')])
lesson(m,'Ordered aggregates and generated columns','Ordered aggregates retain a defined input order inside their aggregate call. A generated column derives its value from a row expression.','Reports need deterministic lists, and repeated row calculations can have a schema-level definition.','Write array_agg(value ORDER BY key). Stored generated columns persist calculated values; PostgreSQL 18 also supports virtual generated columns with additional restrictions. Use explicit STORED for this cross-version familiar example.','Ordering the outer query does not order inputs to array_agg. Generated expressions have restrictions including immutable functions and no subqueries.',[
 task('Category product lists','Return category and product_names as a text array of product names ordered by id, ordered by category.','SELECT category,array_agg(name ORDER BY id) AS product_names FROM products GROUP BY category ORDER BY category;','Intermediate'),
 task('Customer order summaries','Return customer_id and order_ids as a comma-separated string ordered by ordered_on then id for known customers, ordered by customer_id.','SELECT customer_id,string_agg(id::text,\',\' ORDER BY ordered_on,id) AS order_ids FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id ORDER BY customer_id;','Advanced'),
 task('Store a generated line amount','Create invoice_lines(id integer primary key,quantity integer not null,unit_price numeric(10,2) not null,amount numeric generated always as(quantity*unit_price) stored). Insert (1,3,2.50),(2,2,12.50) without specifying amount.','CREATE TABLE invoice_lines(id integer PRIMARY KEY,quantity integer NOT NULL,unit_price numeric(10,2) NOT NULL,amount numeric GENERATED ALWAYS AS(quantity*unit_price) STORED); INSERT INTO invoice_lines(id,quantity,unit_price) VALUES(1,3,2.50),(2,2,12.50);','Advanced',kind='design',validation='SELECT id,quantity,unit_price,amount FROM invoice_lines ORDER BY id;')])


m=module('Real-World SQL Challenges')
lesson(m,'Gaps, islands, and consecutive dates','A gaps-and-islands query identifies runs of adjacent values. The grouping key can be built from the difference between a date and its ordered row number.','Usage streaks, consecutive reservations, and missing periods appear in many analytics tasks.','First remove duplicate dates at the intended grain. Number the ordered dates, subtract the row number in days, then group equal differences into islands.','A repeated date must not advance the streak counter. Decide whether calendar days or business days define adjacency.',[
 task('Consecutive booking start dates','Using distinct booking check_in dates, return island_start, island_end, and day_count for runs of consecutive calendar days, ordered by island_start.','WITH days AS (SELECT DISTINCT check_in AS day FROM bookings), numbered AS (SELECT day,day-(row_number() OVER(ORDER BY day))::integer AS grp FROM days) SELECT min(day) AS island_start,max(day) AS island_end,count(*) AS day_count FROM numbered GROUP BY grp ORDER BY island_start;','Advanced'),
 task('Customer event streaks','Return customer_id, streak_start, streak_end, and active_days for each run of consecutive event dates per customer, counting a date once; order by customer_id then streak_start.','WITH days AS (SELECT DISTINCT customer_id,occurred_at::date AS day FROM events), grouped AS (SELECT customer_id,day,day-(row_number() OVER(PARTITION BY customer_id ORDER BY day))::integer AS grp FROM days) SELECT customer_id,min(day) AS streak_start,max(day) AS streak_end,count(*) AS active_days FROM grouped GROUP BY customer_id,grp ORDER BY customer_id,streak_start;','Advanced'),
 task('Missing July order dates','Return day for dates from 2024-07-01 through 2024-07-07 with no orders, ordered by day.','SELECT d.day::date AS day FROM generate_series(DATE \'2024-07-01\',DATE \'2024-07-07\',INTERVAL \'1 day\') d(day) WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.ordered_on=d.day::date) ORDER BY day;','Advanced')])
lesson(m,'Relational division and every-match rules','An every-match query asks whether all required values have matching facts. This is sometimes called relational division.','A business may need customers who purchased every required category, or products satisfying every selected attribute.','Express every requirement as no missing requirement using nested NOT EXISTS, or compare the distinct matched count with a required count.','Counting rows instead of distinct requirement keys accepts duplicates as if they were new requirements. Define the empty-requirement case deliberately.',[
 task('Office and Tech customers','Return id and name for customers with paid purchases in both Office and Tech categories, ordered by id.','SELECT c.id,c.name FROM customers c WHERE NOT EXISTS(SELECT 1 FROM (VALUES(\'Office\'),(\'Tech\')) required(category) WHERE NOT EXISTS(SELECT 1 FROM orders o JOIN order_items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.customer_id=c.id AND o.status=\'paid\' AND p.category=required.category)) ORDER BY c.id;','Advanced'),
 task('Bought every catalog category','Return customer_id for customers whose paid lines cover every distinct catalog category, ordered by customer_id.','SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.status=\'paid\' AND o.customer_id IS NOT NULL GROUP BY o.customer_id HAVING count(DISTINCT p.category)=(SELECT count(DISTINCT category) FROM products) ORDER BY o.customer_id;','Advanced'),
 task('Products with all required tags','Return id and name of products containing both usb and work tags, ordered by id.','SELECT id,name FROM products WHERE tags @> ARRAY[\'usb\',\'work\'] ORDER BY id;','Intermediate')])
lesson(m,'Percentiles and ordered-set aggregates','A percentile describes a position in an ordered distribution. percentile_cont interpolates; percentile_disc returns an actual input value.','Median and percentile metrics can describe skewed values more usefully than an average alone.','Use WITHIN GROUP (ORDER BY expression) for ordered-set aggregates. A fraction such as 0.5 chooses the median. Cast approximate floating-point output to numeric before decimal rounding.','A percentile of group percentiles is not the overall percentile. Empty inputs and NULL values need explicit handling.',[
 task('Median product price','Return median_price as percentile_cont(0.5) of product prices, rounded to two decimals after casting to numeric.','SELECT round((percentile_cont(0.5) WITHIN GROUP(ORDER BY price))::numeric,2) AS median_price FROM products;','Advanced'),
 task('Department salary medians','Return department and median_salary using percentile_disc(0.5) ordered by salary, output by department.','SELECT department,percentile_disc(0.5) WITHIN GROUP(ORDER BY salary) AS median_salary FROM employees GROUP BY department ORDER BY department;','Advanced'),
 task('Ninetieth percentile order total','Return p90_total as percentile_cont(0.9) of paid order totals, rounded to two decimals after numeric cast.','SELECT round((percentile_cont(0.9) WITHIN GROUP(ORDER BY total))::numeric,2) AS p90_total FROM orders WHERE status=\'paid\';','Advanced')])

m=module('Professional Projects: Commerce and Hospitality')
lesson(m,'Project: an e-commerce customer report','A professional customer report defines eligible orders, result grain, missing-value policy, and ordering before SQL is written.','Teams need one agreed meaning for revenue, repeat purchase, and customer value.','Use paid orders only for revenue, preserve customers with no paid orders, and aggregate at the customer grain before ranking.','A customer with no paid orders should have zero spend, not disappear. Joining lines before summing order totals can overcount.',[
 task('Customer value table','Return customer_id, name, paid_orders, and revenue for every customer; revenue zero if none. Order revenue descending then customer_id.','SELECT c.id AS customer_id,c.name,count(o.id) AS paid_orders,COALESCE(sum(o.total),0) AS revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status=\'paid\' GROUP BY c.id ORDER BY revenue DESC,c.id;','Advanced'),
 task('Customer first and last paid purchase','Return customer_id, first_purchase, last_purchase, and purchase_count for known customers with paid orders, ordered by customer_id.','SELECT customer_id,min(ordered_on) AS first_purchase,max(ordered_on) AS last_purchase,count(*) AS purchase_count FROM orders WHERE status=\'paid\' AND customer_id IS NOT NULL GROUP BY customer_id ORDER BY customer_id;','Advanced'),
 task('Category contribution','Return category, revenue, and revenue_share as paid line revenue divided by all paid line revenue rounded to four decimals; order revenue descending then category.','WITH sales AS (SELECT p.category,sum(i.quantity*i.unit_price) AS revenue FROM products p JOIN order_items i ON i.product_id=p.id JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' GROUP BY p.category) SELECT category,revenue,round(revenue/NULLIF(sum(revenue) OVER(),0),4) AS revenue_share FROM sales ORDER BY revenue DESC,category;','Advanced')])
lesson(m,'Project: inventory replenishment','A replenishment report compares available units with a business target and recent demand.','Stock decisions should distinguish unavailable items from slow or fast sellers.','Compute demand at the product grain, then join it to every product. Keep zero-demand products visible.','A stock value and a sold quantity have different units. Pending and cancelled orders do not count as fulfilled paid demand in this project.',[
 task('Restock to target','Return id, name, stock, and units_to_buy equal to max(20-stock,0), only when positive; order units_to_buy descending then id.','SELECT id,name,stock,greatest(20-stock,0) AS units_to_buy FROM products WHERE stock<20 ORDER BY units_to_buy DESC,id;','Intermediate'),
 task('Paid demand by product','Return product_id, name, sold_units, and stock for every product with zero sold_units when none; order sold_units descending then product_id.','WITH sold AS (SELECT i.product_id,sum(i.quantity) AS sold_units FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' GROUP BY i.product_id) SELECT p.id AS product_id,p.name,COALESCE(s.sold_units,0) AS sold_units,p.stock FROM products p LEFT JOIN sold s ON s.product_id=p.id ORDER BY sold_units DESC,p.id;','Advanced'),
 task('Warehouse stock report','Return warehouse, units, and stock_value by joining inventory to product prices, ordered by stock_value descending then warehouse.','SELECT i.warehouse,sum(i.quantity) AS units,sum(i.quantity*p.price) AS stock_value FROM inventory i JOIN products p ON p.id=i.product_id GROUP BY i.warehouse ORDER BY stock_value DESC,i.warehouse;','Advanced')])
lesson(m,'Project: hotel revenue and occupancy','Hotel data uses intervals rather than isolated dates: a stay occupies nights from check-in through the day before checkout.','Occupancy and revenue depend on correct boundaries and per-night calculations.','Expand stays into nights or use overlap predicates. An adjacent checkout and check-in can share the calendar date without sharing a night.','Counting bookings is not counting occupied room-nights. Applying the full stay price to every expanded night overcounts revenue.',[
 task('Booking charges','Return id, guest, nights, and charge for each booking, ordered by id.','SELECT id,guest,check_out-check_in AS nights,(check_out-check_in)*nightly_rate AS charge FROM bookings ORDER BY id;','Intermediate'),
 task('Room revenue','Return room, occupied_nights, and revenue for all bookings, ordered by revenue descending then room.','SELECT room,sum(check_out-check_in) AS occupied_nights,sum((check_out-check_in)*nightly_rate) AS revenue FROM bookings GROUP BY room ORDER BY revenue DESC,room;','Advanced'),
 task('Daily hotel occupancy','Return day, occupied_rooms (distinct rooms), and revenue for July 1 through July 10 2024, including empty days; each occupied room contributes its booking nightly_rate. Order by day.','SELECT d.day::date AS day,count(DISTINCT b.room) AS occupied_rooms,COALESCE(sum(b.nightly_rate),0) AS revenue FROM generate_series(DATE \'2024-07-01\',DATE \'2024-07-10\',INTERVAL \'1 day\') d(day) LEFT JOIN bookings b ON b.check_in<=d.day::date AND b.check_out>d.day::date GROUP BY d.day ORDER BY d.day;','Advanced')])

m=module('Final Projects: Finance, Analytics, and Reporting')
lesson(m,'Project: a constrained banking ledger','A ledger records movements, while a balance is the accumulated result. Constraints and transactions must support a clear invariant.','Financial applications need traceability and must avoid partial or negative transfers.','Use exact numeric amounts, explicit keys, and atomic updates. A production ledger also needs idempotency, immutable audit history, authorization, and reconciliation.','A toy transfer is not a complete banking system. Cross-row invariants usually require transactions and a carefully designed write interface.',[
 task('Build a transfer ledger','Create transfers(id integer primary key,source_id integer not null references accounts(id),destination_id integer not null references accounts(id),amount numeric(12,2) not null check(amount>0),check(source_id<>destination_id)). Insert (1,1,2,50).','CREATE TABLE transfers(id integer PRIMARY KEY,source_id integer NOT NULL REFERENCES accounts(id),destination_id integer NOT NULL REFERENCES accounts(id),amount numeric(12,2) NOT NULL CHECK(amount>0),CHECK(source_id<>destination_id)); INSERT INTO transfers VALUES(1,1,2,50);','Advanced',kind='design',validation='SELECT id,source_id,destination_id,amount FROM transfers ORDER BY id;'),
 task('Transfer and record atomically','Create transfer_log(id integer primary key,source_id integer,destination_id integer,amount numeric(12,2)). In one transaction move 40 from account 1 to 2 and insert log row (1,1,2,40).','CREATE TABLE transfer_log(id integer PRIMARY KEY,source_id integer,destination_id integer,amount numeric(12,2)); BEGIN; UPDATE accounts SET balance=balance-40 WHERE id=1; UPDATE accounts SET balance=balance+40 WHERE id=2; INSERT INTO transfer_log VALUES(1,1,2,40); COMMIT;','Advanced',kind='modify',validation="SELECT 'account' AS record_type,id,balance AS amount FROM accounts UNION ALL SELECT 'transfer',id,amount FROM transfer_log ORDER BY record_type,id;"),
 task('Reconcile account shares','Return id, owner, balance, and share of total balance rounded to four decimals, ordered by id.','SELECT id,owner,balance,round(balance/NULLIF(sum(balance) OVER(),0),4) AS share FROM accounts ORDER BY id;','Advanced')])
lesson(m,'Project: customer and event analytics','An analytics metric needs a numerator, denominator, time range, and unit of analysis.','A conversion rate can change merely because the analyst counts events rather than people.','Aggregate first at the chosen grain. Keep distinct people separate from event counts and make missing periods explicit.','A purchase event without a preceding visit still needs an explicit business policy. These fixture reports describe observed events rather than proving causation.',[
 task('Device activity','Return device, event_count, and customer_count as distinct customers for all events, ordered by device.','SELECT payload->>\'device\' AS device,count(*) AS event_count,count(DISTINCT customer_id) AS customer_count FROM events GROUP BY device ORDER BY device;','Advanced'),
 task('Daily purchase event rate','Return day, visit_events, purchase_events, and purchase_per_visit rounded to four decimals, NULL for zero visits, ordered by day.','SELECT occurred_at::date AS day,count(*) FILTER(WHERE kind=\'visit\') AS visit_events,count(*) FILTER(WHERE kind=\'purchase\') AS purchase_events,round((count(*) FILTER(WHERE kind=\'purchase\'))::numeric/NULLIF(count(*) FILTER(WHERE kind=\'visit\'),0),4) AS purchase_per_visit FROM events GROUP BY day ORDER BY day;','Advanced'),
 task('Join-month cohort spend','Return cohort_month (first day of customer join month), customer_count (all joined customers), and paid_revenue including zero, ordered by cohort_month.','WITH customer_revenue AS (SELECT c.id,c.joined_on,COALESCE(sum(o.total),0) AS revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status=\'paid\' GROUP BY c.id) SELECT date_trunc(\'month\',joined_on)::date AS cohort_month,count(*) AS customer_count,sum(revenue) AS paid_revenue FROM customer_revenue GROUP BY cohort_month ORDER BY cohort_month;','Advanced')])
lesson(m,'Capstone: reliable monthly business reporting','A reliable report combines correct calculations, deterministic results, documented assumptions, and checks for edge cases.','Professional SQL work is reviewed and maintained by people who did not write its first version.','Break the report into named stages, test empty and duplicate cases, compare totals, inspect a plan, and communicate which facts the data can support.','Do not hide unknown customer IDs or silently mix cancelled sales into revenue. Explain every business filter and denominator.',[
 task('Complete monthly revenue report','Return month_start, paid_orders, paid_revenue, and unique_customers for paid orders, counting known distinct customers only; order by month_start.','SELECT date_trunc(\'month\',ordered_on)::date AS month_start,count(*) AS paid_orders,sum(total) AS paid_revenue,count(DISTINCT customer_id) AS unique_customers FROM orders WHERE status=\'paid\' GROUP BY month_start ORDER BY month_start;','Advanced',kind='complete',starter='SELECT -- month_start, paid_orders, paid_revenue, unique_customers\nFROM orders\n-- Apply the business filter and group by month\n;'),
 task('Month-over-month growth','Return month_start, revenue, previous_revenue, and growth_rate as (revenue-previous)/previous rounded to four decimals, NULL when previous is absent or zero; use paid orders only and order by month_start.','WITH monthly AS (SELECT date_trunc(\'month\',ordered_on)::date AS month_start,sum(total) AS revenue FROM orders WHERE status=\'paid\' GROUP BY month_start), compared AS (SELECT *,lag(revenue) OVER(ORDER BY month_start) AS previous_revenue FROM monthly) SELECT month_start,revenue,previous_revenue,round((revenue-previous_revenue)/NULLIF(previous_revenue,0),4) AS growth_rate FROM compared ORDER BY month_start;','Advanced'),
 task('Cross-check order and line totals','Return order_id, header_total, line_total, and difference (header minus line total) for all orders, with a zero line total if no lines; order by order_id.','WITH lines AS (SELECT order_id,sum(quantity*unit_price) AS line_total FROM order_items GROUP BY order_id) SELECT o.id AS order_id,o.total AS header_total,COALESCE(l.line_total,0) AS line_total,o.total-COALESCE(l.line_total,0) AS difference FROM orders o LEFT JOIN lines l ON l.order_id=o.id ORDER BY o.id;','Advanced')])


