def extra(title,e,**fields):
    l=by_title[title];e['id']=f"{l['id']}-e{len(l['exercises'])+1}";e.update(fields);l['exercises'].append(e)
extra('NULL and three-valued logic',task('Predict an unknown comparison','Predict the rows returned by the visible query. Enter a JSON array of rows; each non-NULL cell is a string and SQL NULL is JSON null. Do not run the query until you have reasoned about WHERE.','SELECT x FROM (VALUES (NULL::integer),(2),(2)) AS values_table(x) WHERE x <> 2;','Intermediate',kind='predict',starter='SELECT x\nFROM (VALUES (NULL::integer),(2),(2)) AS values_table(x)\nWHERE x <> 2;',hints=['Evaluate each input row independently.','A comparison involving NULL is unknown, and WHERE keeps only true.','The two known values equal 2, while the missing value cannot prove inequality.'],explanation='The expected result is an empty array: []. The comparison 2 <> 2 is false, and NULL <> 2 is unknown. Neither qualifies for WHERE.'))
extra('ROW_NUMBER, RANK, and DENSE_RANK',task('Predict tied ranks','Predict all four result rows of the visible query, including the duplicate salary row. Enter a JSON array of rows containing strings.','SELECT salary,rank() OVER(ORDER BY salary DESC) AS salary_rank,dense_rank() OVER(ORDER BY salary DESC) AS dense_salary_rank FROM (VALUES(90),(80),(80),(70)) AS salaries(salary) ORDER BY salary DESC;','Advanced',kind='predict',starter='SELECT salary,\n       rank() OVER (ORDER BY salary DESC) AS salary_rank,\n       dense_rank() OVER (ORDER BY salary DESC) AS dense_salary_rank\nFROM (VALUES (90),(80),(80),(70)) AS salaries(salary)\nORDER BY salary DESC;',hints=['Equal ordering values are peers and receive the same rank.','RANK leaves a gap after the tied pair, while DENSE_RANK counts distinct peer groups.','Start at rank 1 for salary 90, then compare both 80 rows before assigning the 70 row.'],explanation='The rows are [["90","1","1"],["80","2","2"],["80","2","2"],["70","4","3"]]. RANK advances by row positions; DENSE_RANK advances once for each distinct salary.'))
extra('IN, BETWEEN, and ranges',task('Choose correct June date predicates','Select every predicate that correctly selects all and only dates in June 2024 when ordered_on has type DATE. Consider data beyond the installed fixtures.','SELECT true AS correct;','Intermediate',kind='choose',hints=['Check the year as well as the month.','A DATE value has no time-of-day component.','An exclusive July 1 upper bound and an inclusive June 30 upper bound both work for DATE.'],explanation='A half-open June 1 to July 1 range is correct. BETWEEN June 1 and June 30 is also correct for a DATE column. Month number alone includes other years; <= July 1 includes an extra day.'),choices=[dict(id='A',text="ordered_on >= DATE '2024-06-01' AND ordered_on < DATE '2024-07-01'"),dict(id='B',text="ordered_on BETWEEN DATE '2024-06-01' AND DATE '2024-06-30'"),dict(id='C',text="ordered_on >= DATE '2024-06-01' AND ordered_on <= DATE '2024-07-01'"),dict(id='D',text="EXTRACT(MONTH FROM ordered_on) = 6")],correctChoiceIDs=['A','B'])
extra('SQL injection and parameterized queries',task('Choose safe value binding','Choose the approach that treats an untrusted customer name as a value rather than SQL syntax. The pseudocode names are illustrative.','SELECT true AS correct;','Intermediate',kind='choose',hints=['SQL structure and parameter values must travel separately.','A typed $1 placeholder represents a value, not an identifier.','Concatenation can turn quotes and operators in the input into SQL structure.'],explanation='A driver-bound value for $1 cannot change the command structure. String concatenation and interpolating manually quoted input are unsafe. Dynamic identifiers require a separate safe composition strategy.'),choices=[dict(id='A',text='Execute SELECT id FROM customers WHERE name=$1, supplying the name through the driver parameter-binding API.'),dict(id='B',text='Concatenate the raw name after WHERE name= and execute the resulting text.'),dict(id='C',text='Surround the raw name with single quotes using string interpolation and execute it.'),dict(id='D',text='Reject only names containing the word DROP, then concatenate the rest.')],correctChoiceIDs=['A'])
extra('ACID and snapshot visibility',task('Explain two reads and one concurrent commit','A transaction reads an account balance. Another transaction commits a new balance. The first transaction reads the balance again. Explain the possible result under READ COMMITTED and REPEATABLE READ, and explain why a SERIALIZABLE application still needs retry logic. This written answer is self-assessed against a model explanation.','SELECT true AS discussed;','Advanced',kind='explain',hints=['Separate a statement snapshot from a transaction snapshot.','Consider whether the second SELECT obtains a new snapshot.','Distinguish isolation guarantees from a promise that every transaction will commit.'],explanation='Read your answer against the model, identify missing points, and mark it reviewed when you can explain the distinction in your own words.'),modelAnswer='Under READ COMMITTED, each statement obtains a new snapshot. The second SELECT can see the newly committed balance. Under REPEATABLE READ, both reads use the transaction snapshot, so a newly committed external change is not visible to the second read. SERIALIZABLE adds protection against serialization anomalies, but PostgreSQL can abort a transaction with a serialization failure. The application must retry the entire transaction, with bounded retry policy and no duplicated external side effects.')
extra('Capstone: reliable monthly business reporting',task('Explain a revenue reconciliation mismatch','A paid-order report sums orders.total. A line report sums quantity*unit_price after joining order_items. Their totals differ. Explain at least four checks you would perform before changing either query. This answer is self-assessed; no English string matching is used.','SELECT true AS discussed;','Advanced',kind='explain',hints=['Compare the exact eligible order sets and result grains.','Look for missing lines, duplicate joins, guest customers, and different status or date predicates.','Consider business amounts outside line prices, such as tax, delivery, discounts, and refunds.'],explanation='Use the worked explanation as a review rubric, then mark the exercise reviewed only when your explanation covers both SQL correctness and business definitions.'),modelAnswer='First compare status and time filters so both reports use the same eligible orders. Check whether inner joins remove guest or line-less orders. Verify join cardinality so header totals are not repeated for each line and lines are not duplicated by another relationship. Reconcile per order before comparing grand totals. Check whether header totals include tax, shipping, discounts, refunds, or rounding that line totals exclude. Inspect NULL handling and currency units. Preserve a deterministic per-order discrepancy report and confirm the intended business definition with the report owner.')

