# Catalog-based checks supplement state queries for every schema/data exercise.
# Names of constraints and indexes are deliberately excluded; their definitions matter.
SCHEMA_SQL = r"""
SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.table_name),'[]'::jsonb)
FROM (
 SELECT c.relname AS table_name,c.relkind::text AS kind,c.relrowsecurity AS row_security,c.relforcerowsecurity AS force_row_security,
 pg_get_partkeydef(c.oid) AS partition_key,pg_get_expr(c.relpartbound,c.oid) AS partition_bound,
 (SELECT COALESCE(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity::text,'generated',a.attgenerated::text,'default',regexp_replace(pg_get_expr(d.adbin,d.adrelid),'nextval\(''[^'']*''::regclass\)','nextval(sequence)','g')) ORDER BY a.attnum),'[]'::jsonb) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) AS columns,
 (SELECT COALESCE(jsonb_agg(definition ORDER BY definition),'[]'::jsonb) FROM (SELECT pg_get_constraintdef(k.oid,true) AS definition FROM pg_constraint k WHERE k.conrelid=c.oid) defs) AS constraints,
 (SELECT COALESCE(jsonb_agg(to_jsonb(ix) ORDER BY ix.method,ix.keys::text,ix.predicate,ix.unique_index,ix.nulls_not_distinct),'[]'::jsonb) FROM (SELECT am.amname AS method,i.indisunique AS unique_index,i.indnullsnotdistinct AS nulls_not_distinct,i.indnkeyatts AS key_count,(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid,gs,true) ORDER BY gs) FROM generate_series(1,i.indnatts) gs) AS keys,pg_get_expr(i.indpred,i.indrelid,true) AS predicate FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_am am ON am.oid=ic.relam WHERE i.indrelid=c.oid) ix) AS indexes,
 (SELECT COALESCE(jsonb_agg(to_jsonb(p) ORDER BY p.command,p.using_expression,p.check_expression),'[]'::jsonb) FROM (SELECT p.polcmd::text AS command,p.polpermissive AS permissive,pg_get_expr(p.polqual,p.polrelid,true) AS using_expression,pg_get_expr(p.polwithcheck,p.polrelid,true) AS check_expression FROM pg_policy p WHERE p.polrelid=c.oid) p) AS policies
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname=current_schema() AND c.relkind IN('r','p','v','m')
) s
""".strip()

def with_schema_check(sql):
    return "SELECT jsonb_build_object('state',(SELECT COALESCE(jsonb_agg(to_jsonb(result_rows)),'[]'::jsonb) FROM ("+sql.strip().rstrip(';')+") result_rows),'schema',("+SCHEMA_SQL+")) AS verification;"

CLAUSE_GUIDE=[
 ('WITH RECURSIVE','WITH RECURSIVE names the anchor and recursive working relation. The recursive term reads the prior working rows.'),
 ('WITH ','WITH gives a query stage a name; the final SELECT reads its output.'),
 ('SELECT','SELECT lists output expressions in the requested column order. AS introduces a result alias.'),
 ('FROM','FROM names the input relation. Short aliases qualify columns when names could be ambiguous.'),
 ('JOIN','JOIN combines matching rows. ON defines the relationship; the join type decides which unmatched rows survive.'),
 ('WHERE','WHERE keeps only rows where its Boolean condition is true, before grouping or windows.'),
 ('GROUP BY','GROUP BY chooses the result grain; aggregate functions summarize each group.'),
 ('HAVING','HAVING filters whole groups after their aggregates are known.'),
 ('OVER','OVER defines the partition, order, and optional frame for a window calculation.'),
 ('ORDER BY','ORDER BY establishes output order. Later keys resolve ties in earlier keys.'),
 ('LIMIT','LIMIT restricts the row count after ordering; a deterministic tie-breaker makes that choice reproducible.'),
 ('INSERT','INSERT names target columns and supplies matching values or a source query.'),
 ('UPDATE','UPDATE names the target table; SET defines new values and WHERE limits affected rows.'),
 ('DELETE','DELETE FROM names the target; WHERE chooses which rows are removed.'),
 ('RETURNING','RETURNING exposes values from rows changed by the statement.'),
 ('ON CONFLICT','ON CONFLICT selects the conflict key and merge action; EXCLUDED refers to proposed values.'),
 ('CREATE TABLE','CREATE TABLE declares names, types, defaults, and constraints as a durable contract.'),
 ('CREATE FUNCTION','CREATE FUNCTION declares argument types, return type, language, and a body between dollar-quote delimiters.'),
 ('CREATE PROCEDURE','CREATE PROCEDURE declares a named operation; CALL invokes it.'),
 ('CREATE TRIGGER','CREATE TRIGGER states timing, event, row/statement scope, and the trigger function.'),
 ('CREATE INDEX','CREATE INDEX declares the access method and key expressions; a partial predicate limits indexed rows.'),
 ('CREATE VIEW','CREATE VIEW saves a query definition; callers still choose their final output order.'),
 ('CREATE MATERIALIZED VIEW','CREATE MATERIALIZED VIEW stores query rows; REFRESH recomputes them.'),
 ('ALTER TABLE','ALTER TABLE changes the contract of an existing table; its locks and existing data must be considered.'),
 ('BEGIN','BEGIN opens a transaction; COMMIT keeps changes and ROLLBACK discards them.'),
 ('PREPARE','PREPARE declares a command with typed placeholders such as $1. EXECUTE supplies values separately.'),
 ('EXPLAIN','EXPLAIN displays a plan. ANALYZE executes it; the timing-disabled options here keep structural grading repeatable.'),
 ('VACUUM','VACUUM performs maintenance outside an explicit transaction block; ANALYZE also refreshes planner statistics.')]
TOPIC_NAMES=[
 'Relational thinking','Selecting and shaping results','Predicate construction','Missing values and patterns','Computed values','Whole-table summaries','Grouped reporting','Joining related facts','Join correctness','Queries inside queries','Composing result sets','Changing rows','Reliable write operations','Choosing representations','Time-aware queries','Structured collections','Enforcing data rules','Evolving the data model','Calculations across rows','Analytical result patterns','Reusable reporting relations','Server-side program structure','Automatic behavior and search','Choosing access structures','Measuring query work','Maintaining healthy data','Coordinating transactions','Controlling database access','Recovering and operating databases','Traversing connected data','Specialized PostgreSQL tools','Advanced problem solving','Commerce and hospitality practice','Finance and analytics practice']

